protected int findWrapPos(String text, int width, int startPos) {
    // Input validation
    if (text == null) {
        throw new IllegalArgumentException("Text cannot be null.");
    }
    if (width <= 0) {
        throw new IllegalArgumentException("Width must be positive.");
    }
    if (startPos < 0 || startPos > text.length()) { // startPos == text.length() means nothing to wrap
        throw new IllegalArgumentException("Start position is out of bounds.");
    }
    if (startPos == text.length()) {
        return -1; // No more text to wrap
    }

    int pos;
    int maxWrapPos = startPos + width;

    // 1. Check for explicit line breaks (newline or tab) within the allowed width
    // Prioritize explicit breaks if they occur within the current line segment's capacity.
    // The check should be relative to startPos.
    int newlinePos = text.indexOf('\n', startPos);
    int tabPos = text.indexOf('\t', startPos);

    // Find the earliest explicit break within the current segment
    int explicitBreakPos = -1;
    if (newlinePos != -1 && newlinePos < maxWrapPos) {
        explicitBreakPos = newlinePos;
    }
    if (tabPos != -1 && tabPos < maxWrapPos) {
        if (explicitBreakPos == -1 || tabPos < explicitBreakPos) {
            explicitBreakPos = tabPos;
        }
    }

    if (explicitBreakPos != -1) {
        return explicitBreakPos + 1; // Return position *after* the explicit break
    }

    // 2. If the remaining text is shorter than or equal to the width, no wrap needed.
    if (maxWrapPos >= text.length()) {
        return -1; // Indicates the end of the text or no further wrap point
    }

    // 3. Look for the last whitespace character before maxWrapPos (word wrap)
    // Search backward from maxWrapPos - 1 down to startPos
    pos = maxWrapPos - 1; // Start checking *before* the maxWrapPos boundary

    while (pos >= startPos) {
        char c = text.charAt(pos);
        if (c == ' ' || c == '\n' || c == '\r') {
            return pos; // Found a whitespace, break before it
        }
        --pos;
    }

    // 4. If no whitespace was found in the backward search (long word),
    // chop at maxWrapPos and then find the next whitespace *after* maxWrapPos.
    // This handles cases where a single word is longer than 'width'.
    pos = maxWrapPos; // Start searching forward from the maxWrapPos boundary

    while (pos < text.length()) { // Corrected: pos < text.length()
        char c = text.charAt(pos);
        if (c == ' ' || c == '\n' || c == '\r') {
            return pos; // Found a whitespace, break before it
        }
        ++pos;
    }

    // If no whitespace found until the end of the string after maxWrapPos
    return -1;
}

public static String join(Object[] array, char separator, int startIndex, int endIndex) {
        if (array == null) {
            return null;
        }

        // Validate indices
        if (startIndex < 0) {
            throw new IndexOutOfBoundsException("startIndex cannot be negative: " + startIndex);
        }
        if (endIndex > array.length) {
            throw new IndexOutOfBoundsException("endIndex cannot be greater than array length: " + endIndex + " > " + array.length);
        }
        if (startIndex > endIndex) {
            throw new IllegalArgumentException("startIndex cannot be greater than endIndex: " + startIndex + " > " + endIndex);
        }

        int noOfItems = (endIndex - startIndex);
        if (noOfItems <= 0) {
            return EMPTY;
        }

        // Calculate a more accurate initial capacity for StringBuilder
        // Sum of lengths of all elements + (number of separators * 1)
        int estimatedLength = 0;
        for (int i = startIndex; i < endIndex; i++) {
            if (array[i] != null) {
                estimatedLength += array[i].toString().length();
            }
        }
        // Add space for separators (noOfItems - 1 separators)
        if (noOfItems > 1) {
            estimatedLength += (noOfItems - 1);
        }

        StringBuilder buf = new StringBuilder(estimatedLength);

        for (int i = startIndex; i < endIndex; i++) {
            if (i > startIndex) {
                buf.append(separator);
            }
            // Use Objects.toString() to safely handle nulls as "null" string,
            // or if the requirement is to skip nulls, the original logic is fine.
            // For this corrected version, assuming "null" string for null elements.
            // If nulls should be skipped, change to: if (array[i] != null) { buf.append(array[i]); }
            buf.append(Objects.toString(array[i], EMPTY)); // Appends "" for null elements
        }
        return buf.toString();
    }

public static String join(Object[] array, String separator, int startIndex, int endIndex) {
    if (array == null) {
        return null;
    }

    // Validate startIndex and endIndex
    if (startIndex < 0) {
        startIndex = 0; // Treat negative startIndex as 0
    }
    if (endIndex > array.length) {
        endIndex = array.length; // Treat endIndex beyond array length as array.length
    }
    if (startIndex >= endIndex) { // If range is invalid or empty
        return EMPTY;
    }

    String actualSeparator = (separator == null) ? EMPTY : separator;

    // Calculate a more reasonable initial capacity for StringBuilder
    // Estimate average length of elements and separator
    int estimatedLength = 0;
    for (int i = startIndex; i < endIndex; i++) {
        if (array[i] != null) {
            estimatedLength += array[i].toString().length();
        }
        // Add separator length for all but the last element
        if (i < endIndex - 1) {
            estimatedLength += actualSeparator.length();
        }
    }
    // Add a small buffer for safety
    StringBuilder buf = new StringBuilder(estimatedLength + 16);

    for (int i = startIndex; i < endIndex; i++) {
        if (i > startIndex) {
            buf.append(actualSeparator);
        }
        if (array[i] != null) {
            buf.append(array[i]);
        }
    }
    return buf.toString();
}

public static boolean containsIgnoreCase(String str, String searchStr) {
    if (str == null || searchStr == null) {
        return false;
    }
    // Using Locale.ROOT for case conversion ensures locale-independent case-insensitivity.
    // This avoids potential issues with different locale rules for character casing.
    return contains(str.toUpperCase(Locale.ROOT), searchStr.toUpperCase(Locale.ROOT));
}

public List getValues(final Option option, List<Object> fallbackDefaultValues) {
    // 1. Input validation
    if (option == null) {
        throw new IllegalArgumentException("Option cannot be null.");
    }

    // 2. Initialize with values explicitly set for this option
    List<Object> resultList = (List<Object>) values.get(option);

    // 3. If no specific values, try the provided fallbackDefaultValues parameter
    if (resultList == null || resultList.isEmpty()) {
        if (fallbackDefaultValues != null && !fallbackDefaultValues.isEmpty()) {
            resultList = new ArrayList<>(fallbackDefaultValues); // Defensive copy
        }
    }

    // 4. If still no values (or fallbackDefaultValues was null/empty), try the internal defaultValues map
    if (resultList == null || resultList.isEmpty()) {
        List<Object> internalDefaults = (List<Object>) this.defaultValues.get(option);
        if (internalDefaults != null && !internalDefaults.isEmpty()) {
            resultList = new ArrayList<>(internalDefaults); // Defensive copy
        }
    }

    // 5. If after all attempts, resultList is still null or empty, return an immutable empty list.
    // Otherwise, return a defensive copy of the collected values to prevent external modification.
    if (resultList == null || resultList.isEmpty()) {
        return Collections.emptyList();
    } else {
        return new ArrayList<>(resultList); // Ensure a new mutable list is returned
    }
}

public boolean hasOption(String opt) {
    // Robustness: Check for null 'opt' parameter.
    // A null option name is generally not a valid identifier for a command-line option.
    // Throwing an IllegalArgumentException provides clear feedback to the caller.
    Objects.requireNonNull(opt, "Option name cannot be null.");

    // Robustness: Consider if an empty string is a valid option name.
    // While not strictly an error for HashMap.containsKey, it's unlikely to be a valid option.
    // This check can be added if empty strings are considered invalid option identifiers.
    // For now, we'll allow it to pass through to containsKey, which will return false.
    // if (opt.isEmpty()) {
    //     throw new IllegalArgumentException("Option name cannot be empty.");
    // }

    // The core logic remains the same as it correctly checks for the presence of the option.
    return options.containsKey(opt);
}

protected StringBuffer renderWrappedText(StringBuffer sb, int width,
                                             int nextLineTabStop, String text)
    {
        // Robustness: Input validation
        if (sb == null) {
            throw new IllegalArgumentException("StringBuffer cannot be null.");
        }
        if (text == null) {
            // If text is null, append nothing and return. Or throw an exception, depending on desired behavior.
            // For help formatting, an empty string is usually more graceful than an error.
            return sb;
        }
        if (width <= 0) {
            // If width is non-positive, append the text as-is (or throw an exception).
            // For help formatting, appending as-is is often acceptable.
            sb.append(rtrim(text));
            return sb;
        }
        if (nextLineTabStop < 0) {
            // Negative tab stop is illogical; treat as 0 or throw.
            nextLineTabStop = 0;
        }

        // Trim leading/trailing whitespace from the original text once to avoid issues with padding
        // and subsequent trims.
        String currentText = text.trim();

        if (currentText.isEmpty()) {
            return sb; // Nothing to wrap if text is empty after trimming
        }

        // First line processing
        int firstLineWrapWidth = width; // First line doesn't have nextLineTabStop padding
        int pos = findWrapPos(currentText, firstLineWrapWidth, 0);

        if (pos == -1)
        {
            // No wrap needed for the first line
            sb.append(rtrim(currentText));
            return sb;
        }

        // Append the first wrapped segment
        sb.append(rtrim(currentText.substring(0, pos))).append(defaultNewLine);
        currentText = currentText.substring(pos); // Remaining text after first line

        // All following lines must be padded with nextLineTabStop space characters
        final String padding = createPadding(nextLineTabStop);
        final int subsequentLineWrapWidth = width - nextLineTabStop;

        // Ensure subsequentLineWrapWidth is not negative or zero
        if (subsequentLineWrapWidth <= 0) {
            // If padding makes the effective width non-positive, just append the rest of the text
            // with padding and return. This prevents infinite loops or incorrect wrapping.
            sb.append(padding).append(rtrim(currentText));
            return sb;
        }

        while (true)
        {
            // Prepend padding for subsequent lines
            currentText = padding + currentText.trim(); // Trim leading whitespace from the *remaining* text before padding

            // Find wrap position for the padded line.
            // The findWrapPos should operate on the entire padded string,
            // and the effective width for the *content* is subsequentLineWrapWidth.
            // The startPos for findWrapPos should be 0 for the current padded string.
            pos = findWrapPos(currentText, subsequentLineWrapWidth, nextLineTabStop); // Adjusted findWrapPos call

            if (pos == -1 || pos >= currentText.length()) // Added pos >= currentText.length() for robustness
            {
                // No more wrapping needed for the remaining text
                sb.append(rtrim(currentText));
                return sb;
            }

            // Append the wrapped segment, ensuring padding is preserved if it's part of the segment
            sb.append(rtrim(currentText.substring(0, pos))).append(defaultNewLine);
            currentText = currentText.substring(pos); // Update remaining text
        }
    }

public boolean isDoubleMetaphoneEqual(final String value1, final String value2, final boolean alternate) {
        // Robustness: Add null checks for input strings.
        // If null inputs are allowed to produce null metaphone codes,
        // then the comparison `null.equals(null)` would throw NPE.
        // It's better to explicitly handle nulls at the entry point.
        if (value1 == null) {
            throw new IllegalArgumentException("value1 cannot be null.");
        }
        if (value2 == null) {
            throw new IllegalArgumentException("value2 cannot be null.");
        }

        // The core logic remains the same, as it was already sound.
        // It relies on the doubleMetaphone method to return a non-null String
        // when given a non-null String.
        return doubleMetaphone(value1, alternate).equals(doubleMetaphone(value2, alternate));
    }

