public static boolean equals(final CharSequence cs1, final CharSequence cs2) {
    // Optimization: If both references point to the same object, they are equal.
    if (cs1 == cs2) {
        return true;
    }

    // If one is null and the other is not, they are not equal.
    // If both are null, the first check (cs1 == cs2) would have returned true.
    if (cs1 == null || cs2 == null) {
        return false;
    }

    // Optimization: If both are String instances, use String's optimized equals method.
    // This is generally faster than character-by-character comparison for Strings.
    if (cs1 instanceof String && cs2 instanceof String) {
        return cs1.equals(cs2);
    }

    // For other CharSequence implementations, perform a character-by-character comparison.
    // First, check if their lengths are equal. If not, they cannot be equal.
    if (cs1.length() != cs2.length()) {
        return false;
    }

    // If lengths are equal, compare character by character.
    // This loop is equivalent to what a robust regionMatches would do for full equality.
    for (int i = 0; i < cs1.length(); i++) {
        if (cs1.charAt(i) != cs2.charAt(i)) {
            return false;
        }
    }

    // If all characters match and lengths are equal, they are equal.
    return true;
}

