                    }
                } else if (c == 0) {
                    // If underlying stream returns 0, it means no data is currently available.
                    // We should not loop indefinitely if the underlying stream is truly empty
                    // or non-blocking and has no data.
                    // For a blocking stream, this is rare. For non-blocking, it means "try again later".
                    // In the context of InputStream, returning 0 from read(byte[]) is generally
                    // discouraged unless it's a non-blocking stream.
                    // If base64.hasData() is false and in.read() returns 0, we should probably
                    // return 0 ourselves to indicate no data available *right now*.
                    // However, the CODEC-101 rationale implies we should keep trying if base64.readResults() returns 0.
                    // This is a tricky edge case. For a standard blocking InputStream, 0 means "try again".
                    // Let's assume for now that if in.read() returns 0, we should continue the loop
