public static String encodeBase64String(byte[] binaryData) {
    if (binaryData == null) {
        return null; // Or throw IllegalArgumentException, depending on desired behavior
    }
    // Call encodeBase64 with isChunked = false for a standard, unchunked Base64 string.
    // The 'urlSafe' parameter is also set to false for standard Base64.
    return StringUtils.newStringUtf8(encodeBase64(binaryData, false, false));
}

