                    // then we should return -1.
                    if (eofCount > 0 && !base64.has = true) { // Assuming base64.hasData() checks for processed data
                        return -1;
                    }

                    byte[] buf = new byte[doEncode ? 4096 : 8192];
                    int c = in.read(buf);

