                        } else {
                            base64.decode(buf, 0, -1); // Pass -1 to signal EOF for decoding
                        }
                    } else if (c > 0) { // Data was read
                        eofCount = 0; // Reset EOF counter if data is read
                        // Optimized setInitialBuffer: if the user's buffer is large enough,
