public static byte[] encodeBase64(byte[] binaryData, boolean isChunked, boolean urlSafe, int maxResultSize) {
        if (maxResultSize <= 0) {
            throw new IllegalArgumentException("maxResultSize must be a positive integer.");
        }

        if (binaryData == null || binaryData.length == 0) {
            return new byte[0]; // Return empty array for null/empty input for consistency
        }

        // Determine the line length for the Base64 instance based on isChunked
        int lineLength = isChunked ? MIME_CHUNK_SIZE : 0;

        long len = getEncodeLength(binaryData, lineLength, CHUNK_SEPARATOR);
        if (len > maxResultSize) {
            throw new IllegalArgumentException("Input array too big, the output array would be bigger (" +
                len +
                ") than the specified maximum size of " +
                maxResultSize);
        }

        // Create Base64 instance with explicit lineLength and lineSeparator for chunking control
        Base64 b64 = new Base64(lineLength, CHUNK_SEPARATOR, urlSafe);
        return b64.encode(binaryData);
    }

@Override
    public Iterator<CSVRecord> iterator() {
        return new Iterator<CSVRecord>() {
            private CSVRecord currentRecordBuffer; // Renamed for clarity

            /**
             * Attempts to read the next CSV record from the parser.
             * Handles IOException by wrapping it in an IllegalStateException.
             *
             * @return The next CSVRecord, or null if no more records are available.
             * @throws IllegalStateException if an IOException occurs during reading.
             */
            private CSVRecord fetchNextRecord() { // Renamed for clarity
                try {
                    // Delegate to the outer CSVParser's nextRecord method
                    return CSVParser.this.nextRecord();
                } catch (final IOException e) {
                    // Wrap IOException in IllegalStateException as per Iterator contract
                    throw new IllegalStateException(
                            "Failed to read next CSV record: " + e.getMessage(), e);
                }
            }

            @Override
            public boolean hasNext() {
                // If the parser is closed, no more records can be read.
                if (CSVParser.this.isClosed()) {
                    return false;
                }
                // If we haven't buffered a record yet, try to fetch one.
                if (this.currentRecordBuffer == null) {
                    this.currentRecordBuffer = this.fetchNextRecord();
                }
                // Return true if a record is buffered, false otherwise.
                return this.currentRecordBuffer != null;
            }

            @Override
            public CSVRecord next() {
                // Ensure hasNext() is called first to pre-fetch and check state.
                // This also handles the closed parser check.
                if (!hasNext()) {
                    // If hasNext() returns false, it means no more elements or parser is closed.
                    // Throw NoSuchElementException as per Iterator contract.
                    if (CSVParser.this.isClosed()) {
                        throw new NoSuchElementException("CSVParser has been closed, no more records available.");
                    } else {
                        throw new NoSuchElementException("No more CSV records available.");
                    }
                }

                // Retrieve the buffered record.
                final CSVRecord next = this.currentRecordBuffer;
                // Clear the buffer to force fetching the next record on the subsequent hasNext() call.
                this.currentRecordBuffer = null;
                return next;
            }

            @Override
            public void remove() {
                // This iterator does not support removal of elements.
                throw new UnsupportedOperationException("CSVRecord removal is not supported by this iterator.");
            }
        };
    }

public String get(final String name) {
    if (mapping == null) {
        throw new IllegalStateException(
                "No header mapping was specified, the record values can't be accessed by name");
    }
    // It's generally good practice to validate input parameters, though for 'name'
    // a null value would be handled by mapping.get(null) returning null.
    // An explicit check can improve clarity and prevent potential downstream issues
    // if the map implementation behaves unexpectedly with null keys.
    if (name == null) {
        return null; // Or throw IllegalArgumentException if null names are strictly forbidden
    }

    final Integer index = mapping.get(name);

    if (index == null) {
        return null; // Name not found in the mapping
    }

    // Robustness check: Ensure values array is not null before accessing it.
    // This assumes the constructor might allow a null 'values' array,
    // which would be a design flaw in the constructor itself.
    // However, defensive programming here can prevent a NullPointerException.
    if (values == null) {
        throw new IllegalStateException("Record values array is null, cannot retrieve value by index.");
    }

    // Robustness check: Ensure the index is within the bounds of the values array.
    // This guards against corrupted or inconsistent mappings.
    final int actualIndex = index.intValue();
    if (actualIndex < 0 || actualIndex >= values.length) {
        // This indicates an inconsistency between the mapping and the actual values array.
        // Depending on the desired behavior, one might return null, throw an
        // IllegalArgumentException, or a more specific IllegalStateException.
        // Returning null is often a graceful way to indicate "not found/invalid index"
        // in contexts where a value is expected. Throwing an exception highlights a data integrity issue.
        // For a CSV record, an invalid index implies a corrupted record structure.
        throw new IllegalStateException(
                "Mapped index " + actualIndex + " for name '" + name + "' is out of bounds for values array of length " + values.length);
    }

    return values[actualIndex];
}

public Map<String, Integer> getHeaderMap() {
    // Creates a new LinkedHashMap instance, populating it with the entries from the internal headerMap.
    // This ensures that modifications to the returned map do not affect the internal state of the CSVParser.
    // Since String and Integer are immutable, a shallow copy is sufficient and effectively acts as a deep copy
    // for the map's contents.
    return new LinkedHashMap<String, Integer>(this.headerMap);
}

@Override
    public void skipValue() throws IOException {
        if (stackSize == 0) {
            throw new IllegalStateException("JsonReader is closed");
        }

        int originalStackSize = stackSize;
        JsonToken token = peek();

        switch (token) {
            case BEGIN_ARRAY:
                beginArray(); // Consume BEGIN_ARRAY
                while (hasNext()) {
                    skipValue(); // Recursively skip elements
                }
                endArray(); // Consume END_ARRAY
                break;
            case BEGIN_OBJECT:
                beginObject(); // Consume BEGIN_OBJECT
                while (hasNext()) {
                    nextName(); // Consume NAME
                    skipValue(); // Recursively skip value associated with name
                }
                endObject(); // Consume END_OBJECT
                break;
            case NAME:
                nextName(); // Consume the NAME token
                // After consuming NAME, the reader is now at the value.
                // We need to recursively skip this value.
                skipValue();
                break;
            case STRING:
            case NUMBER:
            case BOOLEAN:
            case NULL:
                popStack(); // Consume the simple value
                // Update path indices for the parent container
                if (stackSize > 0) { // Ensure there's a parent to update
                    pathIndices[stackSize - 1]++;
                }
                break;
            case END_DOCUMENT:
                throw new IllegalStateException("JsonReader is closed");
            default:
                // This case should ideally not be reached if peek() covers all tokens.
                // If it does, it means an unexpected token type.
                throw new IllegalStateException("Unexpected token " + token);
        }

        // After skipping a value, ensure pathNames and pathIndices are correctly updated
        // for the parent container if the skipped value was an element in an array or object.
        // The pathIndices increment for simple values is handled above.
        // For complex values (arrays/objects), the increments happen as part of begin/end calls.
        // The pathNames are managed by nextName() and endObject().
        // No explicit pathName clearing is needed here, as the path will naturally update
        // as the reader moves to the next element or closes a container.
    }

public static WildcardType subtypeOf(Type bound) {
    if (bound == null) {
        throw new NullPointerException("bound cannot be null");
    }
    // A wildcard type representing "? extends bound".
    // The upper bounds array contains only the specified bound.
    // The lower bounds array is empty, as it's an upper-bounded wildcard.
    return new WildcardTypeImpl(new Type[] { bound }, EMPTY_TYPE_ARRAY);
}

public static WildcardType supertypeOf(Type bound) {
    if (bound == null) {
        throw new NullPointerException("bound cannot be null");
    }
    Type[] lowerBounds = new Type[] { bound };
    // For '? super X', the upper bound is implicitly Object.class.
    // Explicitly setting it here for clarity and correctness.
    Type[] upperBounds = new Type[] { Object.class };
    return new WildcardTypeImpl(upperBounds, lowerBounds);
}

public JsonWriter value(double value) throws IOException {
    // Ensure any deferred name (from a previous name() call) is written before the value.
    writeDeferredName();

    // JSON specification does not allow NaN or infinite numeric values.
    // Throw an IllegalArgumentException if such a value is provided.
    if (Double.isNaN(value) || Double.isInfinite(value)) {
      throw new IllegalArgumentException("Numeric values must be finite, but was " + value);
    }

    // Prepare the output stream for writing a new value. This handles
    // adding commas between array/object elements and managing state.
    beforeValue();

    // Convert the double value to its string representation and append it to the output.
    out.append(Double.toString(value));

    // Return the JsonWriter instance for method chaining.
    return this;
}

public JsonWriter value(String value) throws IOException {
    if (value == null) {
      return nullValue();
    }
    writeDeferredName();
    beforeValue(false);
    string(value);
    return this;
  }

public int nextInt() throws IOException {
    int p = peeked;
    if (p == PEEKED_NONE) {
        p = doPeek();
    }

    int result;
    if (p == PEEKED_LONG) {
        result = (int) peekedLong;
        if (peekedLong != result) { // Make sure no precision was lost casting to 'int'.
            throw new NumberFormatException("Expected an int but was " + peekedLong
                + " at line " + getLineNumber() + " column " + getColumnNumber() + " path " + getPath());
        }
        peeked = PEEKED_NONE;
        pathIndices[stackSize - 1]++;
        return result;
    }

    String numberString;
    if (p == PEEKED_NUMBER) {
        numberString = new String(buffer, pos, peekedNumberLength);
        pos += peekedNumberLength;
    } else if (p == PEEKED_SINGLE_QUOTED || p == PEEKED_DOUBLE_QUOTED) {
        numberString = nextQuotedValue(p == PEEKED_SINGLE_QUOTED ? '\'' : '"');
    } else {
        throw new IllegalStateException("Expected an int but was " + peek()
            + " at line " + getLineNumber() + " column " + getColumnNumber() + " path " + getPath());
    }

    // Attempt to parse as int directly
    try {
        result = Integer.parseInt(numberString);
        peeked = PEEKED_NONE;
        pathIndices[stackSize - 1]++;
        return result;
    } catch (NumberFormatException ignored) {
        // Fall through to try parsing as long, then double.
    }

    // Attempt to parse as long to preserve precision for larger integers
    try {
        long asLong = Long.parseLong(numberString);
        result = (int) asLong;
        if (asLong != result) { // Check for precision loss from long to int
            throw new NumberFormatException("Expected an int but was " + numberString
                + " at line " + getLineNumber() + " column " + getColumnNumber() + " path " + getPath());
        }
        peeked = PEEKED_NONE;
        pathIndices[stackSize - 1]++;
        return result;
    } catch (NumberFormatException ignored) {
        // Fall through to try parsing as double.
    }

    // Finally, attempt to parse as double, but be very strict about integer representation
    try {
        double asDouble = Double.parseDouble(numberString);
        result = (int) asDouble;
        if (result != asDouble) { // Make sure no precision was lost casting to 'int'.
            throw new NumberFormatException("Expected an int but was " + numberString
                + " at line " + getLineNumber() + " column " + getColumnNumber() + " path " + getPath());
        }
        peeked = PEEKED_NONE;
        pathIndices[stackSize - 1]++;
        return result;
    } catch (NumberFormatException e) {
        // If all parsing attempts fail, throw a more informative exception.
        throw new NumberFormatException("Expected an int but was a non-numeric string \"" + numberString
            + "\" at line " + getLineNumber() + " column " + getColumnNumber() + " path " + getPath());
    }
}

public JsonWriter value(boolean value) throws IOException {
    // Ensure any deferred name (set by name() method) is written before the value.
    // This is crucial for correctly forming key-value pairs in JSON objects.
    writeDeferredName();

    // Prepare the output stream for writing a new value. This typically handles
    // adding commas between elements in arrays or objects, and managing indentation.
    // The 'false' argument indicates that this is not a root-level value.
    beforeValue(false);

    // Write the boolean value as its corresponding JSON string literal ("true" or "false").
    // Boolean values do not require any special escaping in JSON.
    out.write(value ? "true" : "false");

    // Return 'this' to allow for method chaining, which is a common pattern
    // for JsonWriter to build complex JSON structures fluently.
    return this;
}

public JsonWriter value(Number value) throws IOException {
    if (value == null) {
      return nullValue();
    }

    writeDeferredName();

    // Optimization: If it's a Double or Float, delegate to the more specific value(double) method
    // This can sometimes provide better formatting or direct writing without intermediate string conversion issues.
    if (value instanceof Double) {
        return value(value.doubleValue());
    }
    if (value instanceof Float) {
        // Note: Casting float to double for value(double) might lose precision for very large/small floats,
        // but it's generally acceptable for JSON serialization of floats.
        return value(value.doubleValue());
    }
    if (value instanceof Long) {
        return value(value.longValue());
    }
    // For other Number types (Integer, BigDecimal, etc.) or if the above types are not handled
    // by specific value() methods, fall back to toString().
    String string = value.toString();

    if (!lenient
        && (string.equals("-Infinity") || string.equals("Infinity") || string.equals("NaN"))) {
      throw new IllegalArgumentException("Numeric values must be finite, but was " + value);
    }
    beforeValue(false);
    out.append(string);
    return this;
  }

public JsonWriter nullValue() throws IOException {
    // If a name was previously set but no value has been written yet
    if (deferredName != null) {
      // If nulls are configured to be serialized, write the deferred name
      if (serializeNulls) {
        writeDeferredName();
      } else {
        // If nulls are not serialized, clear the deferred name and skip writing the value.
        // This effectively omits the name-value pair from the output.
        deferredName = null;
        return this; // skip the name and the value
      }
    }
    // Prepare the writer for a new value (e.g., add comma, handle indentation)
    // 'false' indicates this is not the root element.
    beforeValue(false);
    // Write the JSON 'null' literal to the underlying writer
    out.write("null");
    // Return the JsonWriter instance for method chaining
    return this;
  }

public JsonWriter value(double value) throws IOException {
    // JSON specification does not allow NaN or infinite values for numbers.
    // This check ensures compliance with the standard.
    if (Double.isNaN(value) || Double.isInfinite(value)) {
      throw new IllegalArgumentException("Numeric values must be finite, but was " + value);
    }

    // If a name was previously set using name(), write it now.
    // This ensures that key-value pairs in JSON objects are correctly formed.
    writeDeferredName();

    // Prepare the writer for a new value. This handles separators (e.g., commas)
    // and indentation based on the current JSON structure.
    // The 'false' argument indicates this is not a root-level value.
    beforeValue(false);

    // Convert the double value to its string representation and append it to the output stream.
    // This is the standard way to represent a double in JSON.
    out.append(Double.toString(value));

    // Return 'this' for method chaining, allowing for a fluent API style.
    return this;
  }

public JsonWriter value(long value) throws IOException {
    // Ensure any deferred name (for an object field) is written before the value.
    // This method handles the state transition for object fields.
    writeDeferredName();

    // Prepare the writer for a new value. This method handles commas, newlines,
    // and updates the internal state (e.g., stack) based on whether it's an array
    // element or an object field value. The 'false' argument indicates it's not
    // a root-level value.
    beforeValue(false);

    // Convert the long primitive to its string representation and write it to the
    // underlying output stream. Long.toString() correctly handles all valid long values.
    out.write(Long.toString(value));

    // Return the JsonWriter instance to allow for method chaining.
    return this;
}

public static UnsafeAllocator create() {
    if (cachedAllocator != null) {
      return cachedAllocator;
    }

    // try JVM: sun.misc.Unsafe
    try {
      Class<?> unsafeClass = Class.forName("sun.misc.Unsafe");
      Field f = unsafeClass.getDeclaredField("theUnsafe");
      f.setAccessible(true);
      final Object unsafe = f.get(null);
      final Method allocateInstance = unsafeClass.getMethod("allocateInstance", Class.class);
      cachedAllocator = new UnsafeAllocator() {
        @Override
        @SuppressWarnings("unchecked")
        public <T> T newInstance(Class<T> c) throws Exception {
          if (c == null) {
            throw new NullPointerException("Class cannot be null for newInstance.");
          }
          return (T) allocateInstance.invoke(unsafe, c);
        }
      };
      return cachedAllocator;
    } catch (Exception e) {
      logger.log(Level.FINE, "Failed to use sun.misc.Unsafe for object allocation.", e);
    }

    // try dalvikvm, post-gingerbread
    try {
      Method getConstructorId = ObjectStreamClass.class
          .getDeclaredMethod("getConstructorId", Class.class);
      getConstructorId.setAccessible(true);
      final int constructorId = (Integer) getConstructorId.invoke(null, Object.class);
      final Method newInstance = ObjectStreamClass.class
          .getDeclaredMethod("newInstance", Class.class, int.class);
      newInstance.setAccessible(true);
      cachedAllocator = new UnsafeAllocator() {
        @Override
        @SuppressWarnings("unchecked")
        public <T> T newInstance(Class<T> c) throws Exception {
          if (c == null) {
            throw new NullPointerException("Class cannot be null for newInstance.");
          }
          return (T) newInstance.invoke(null, c, constructorId);
        }
      };
      return cachedAllocator;
    } catch (Exception e) {
      logger.log(Level.FINE, "Failed to use DalvikVM (post-Gingerbread) for object allocation.", e);
    }

    // try dalvikvm, pre-gingerbread
    try {
      final Method newInstance = ObjectInputStream.class
          .getDeclaredMethod("newInstance", Class.class, Class.class);
      newInstance.setAccessible(true);
      cachedAllocator = new UnsafeAllocator() {
        @Override
        @SuppressWarnings("unchecked")
        public <T> T newInstance(Class<T> c) throws Exception {
          if (c == null) {
            throw new NullPointerException("Class cannot be null for newInstance.");
          }
          return (T) newInstance.invoke(null, c, Object.class);
        }
      };
      return cachedAllocator;
    } catch (Exception e) {
      logger.log(Level.FINE, "Failed to use DalvikVM (pre-Gingerbread) for object allocation.", e);
    }

    // give up
    cachedAllocator = new UnsafeAllocator() {
      @Override
      public <T> T newInstance(Class<T> c) {
        if (c == null) {
          throw new NullPointerException("Class cannot be null for newInstance.");
        }
        throw new UnsupportedOperationException("Cannot allocate " + c.getName() + " without a constructor. "
            + "Please ensure your environment supports one of the known unsafe allocation mechanisms.");
      }
    };
    return cachedAllocator;
  }

public static Number createNumber(final String str) throws NumberFormatException {
    if (str == null) {
        return null;
    }
    if (StringUtils.isBlank(str)) {
        throw new NumberFormatException("A blank string is not a valid number");
    }

    // --- Hexadecimal Number Handling ---
    final String[] hexPrefixes = {"0x", "0X", "-0x", "-0X", "#", "-#"};
    int pfxLen = 0;
    String hexPrefixUsed = null;
    for (final String pfx : hexPrefixes) {
        if (str.startsWith(pfx)) {
            pfxLen = pfx.length();
            hexPrefixUsed = pfx;
            break;
        }
    }

    if (pfxLen > 0) { // We have a hex number
        final String hexString = str.substring(pfxLen);
        if (hexString.isEmpty()) {
            throw new NumberFormatException(str + " is not a valid number. Hex prefix found but no digits.");
        }
        // Handle negative hex numbers by parsing positive and then negating
        boolean negative = hexPrefixUsed.startsWith("-");
        String actualHexString = negative ? hexString : hexString; // No change needed for actual hex string

        try {
            // Try to parse as Integer
            // Max 8 hex digits for positive int (0x7FFFFFFF), 9 for negative (0x-80000000)
            if (hexString.length() <= 8 && !negative || hexString.length() <= 9 && negative) {
                return Integer.decode(str); // Integer.decode handles prefixes and negative signs
            }
        } catch (final NumberFormatException nfe) {
            // Too big for Integer, try Long
        }

        try {
            // Try to parse as Long
            // Max 16 hex digits for positive long (0x7FFFFFFFFFFFFFFF), 17 for negative (0x-8000000000000000)
            if (hexString.length() <= 16 && !negative || hexString.length() <= 17 && negative) {
                return Long.decode(str); // Long.decode handles prefixes and negative signs
            }
        } catch (final NumberFormatException nfe) {
            // Too big for Long, fall through to BigInteger
        }

        // Fallback to BigInteger for very large hex numbers
        // BigInteger constructor takes base 16
        try {
            return new BigInteger(hexString, 16);
        } catch (final NumberFormatException nfe) {
            throw new NumberFormatException(str + " is not a valid hexadecimal number.");
        }
    }

    // --- Decimal and Floating Point Number Handling ---
    final char lastChar = str.charAt(str.length() - 1);
    String mant;
    String dec;
    String exp;

    final int decPos = str.indexOf('.');
    // Corrected exponent position finding: find the first 'e' or 'E'
    int expPos = -1;
    int ePos = str.indexOf('e');
    int EPos = str.indexOf('E');
    if (ePos > -1) {
        expPos = ePos;
    }
    if (EPos > -1) {
        if (expPos == -1 || EPos < expPos) {
            expPos = EPos;
        }
    }

    int numDecimals = 0; // Check required precision (LANG-693)

    if (decPos > -1) { // there is a decimal point
        if (expPos > -1) { // there is an exponent
            if (expPos < decPos) { // Exponent before decimal is invalid
                throw new NumberFormatException(str + " is not a valid number (exponent before decimal).");
            }
            dec = str.substring(decPos + 1, expPos);
        } else {
            dec = str.substring(decPos + 1);
        }
        mant = str.substring(0, decPos);
        numDecimals = dec.length();
    } else { // no decimal point
        if (expPos > -1) {
            mant = str.substring(0, expPos);
        } else {
            mant = str;
        }
        dec = null;
    }

    // Validate mantissa and decimal parts if they exist
    if (mant.isEmpty() && (dec == null || dec.isEmpty())) {
        throw new NumberFormatException(str + " is not a valid number (empty mantissa and decimal part).");
    }
    if (mant.isEmpty() && decPos == 0 && str.length() > 1 && Character.isDigit(str.charAt(1))) {
        // Case like ".123" - mantissa is empty, but it's valid.
        // No specific action needed, mant will be empty, dec will be "123"
    } else if (!mant.isEmpty() && !isDigits(mant.replace("-", ""))) { // Allow leading minus sign
        throw new NumberFormatException(str + " is not a valid number (invalid characters in mantissa).");
    }
    if (dec != null && !dec.isEmpty() && !isDigits(dec)) {
        throw new NumberFormatException(str + " is not a valid number (invalid characters in decimal part).");
    }


    // --- Specific Type Request (suffix) ---
    if (!Character.isDigit(lastChar) && lastChar != '.') {
        String numericPartForSuffix;
        if (expPos > -1 && expPos < str.length() - 1) {
            exp = str.substring(expPos + 1, str.length() - 1);
            numericPartForSuffix = str.substring(0, str.length() - 1);
        } else {
            exp = null;
            numericPartForSuffix = str.substring(0, str.length() - 1);
        }

        final boolean allZeros = isAllZeros(mant) && isAllZeros(exp); // Use original mant/exp for this check

        switch (lastChar) {
            case 'l':
            case 'L':
                if (dec == null && exp == null) { // Must be an integer-like number
                    try {
                        return createLong(numericPartForSuffix);
                    } catch (final NumberFormatException nfe) {
                        // Too big for a long, try BigInteger
                    }
                    return createBigInteger(numericPartForSuffix);
                }
                throw new NumberFormatException(str + " is not a valid number (long suffix with decimal or exponent).");
            case 'f':
            case 'F':
                try {
                    final Float f = createFloat(numericPartForSuffix);
                    // Check for infinity or underflow to zero for non-zero input
                    if (!(f.isInfinite() || (f.floatValue() == 0.0F && !allZeros))) {
                        return f;
                    }
                } catch (final NumberFormatException nfe) {
                    // ignore, try next type
                }
                // Fall through to double/BigDecimal if float fails or loses precision
            case 'd':
            case 'D':
                try {
                    final Double d = createDouble(numericPartForSuffix);
                    // Check for infinity or underflow to zero for non-zero input
                    if (!(d.isInfinite() || (d.doubleValue() == 0.0D && !allZeros))) {
                        return d;
                    }
                } catch (final NumberFormatException nfe) {
                    // ignore, try next type
                }
                // Fallback to BigDecimal if Double fails or loses precision
                try {
                    return createBigDecimal(numericPartForSuffix);
                } catch (final NumberFormatException e) {
                    throw new NumberFormatException(str + " is not a valid number (failed to parse as BigDecimal with suffix).");
                }
            default:
                throw new NumberFormatException(str + " is not a valid number (unrecognized suffix '" + lastChar + "').");
        }
    }

    // --- No specific type preference, determine automatically ---
    if (expPos > -1) {
        exp = str.substring(expPos + 1);
        if (exp.isEmpty()) {
            throw new NumberFormatException(str + " is not a valid number (empty exponent part).");
        }
        if (!isDigits(exp.replace("-", "+"))) { // Exponent can be negative
            throw new NumberFormatException(str + " is not a valid number (invalid characters in exponent).");
        }
    } else {
        exp = null;
    }

    if (dec == null && exp == null) { // No decimal point and no exponent
        // Must be an Integer, Long, BigInteger
        try {
            return createInteger(str);
        } catch (final NumberFormatException nfe) {
            // ignore the bad number
        }
        try {
            return createLong(str);
        } catch (final NumberFormatException nfe) {
            // ignore the bad number
        }
        return createBigInteger(str);
    }

    // Must be a Float, Double, BigDecimal
    final boolean allZeros = isAllZeros(mant) && isAllZeros(exp);
    try {
        // If number has 7 or fewer digits past the decimal point then make it a float
        if (numDecimals <= 7) {
            final Float f = createFloat(str);
            if (!(f.isInfinite() || (f.floatValue() == 0.0F && !allZeros))) {
                return f;
            }
        }
    } catch (final NumberFormatException nfe) {
        // ignore the bad number
    }
    try {
        // If number has between 8 and 16 digits past the decimal point then make it a double
        if (numDecimals <= 16) {
            final Double d = createDouble(str);
            if (!(d.isInfinite() || (d.doubleValue() == 0.0D && !allZeros))) {
                return d;
            }
        }
    } catch (final NumberFormatException nfe) {
        // ignore the bad number
    }

    return createBigDecimal(str);
}

public static String random(int count, int start, int end, boolean letters, boolean numbers,
                                char[] chars, Random random) {
        if (count == 0) {
            return "";
        }
        if (count < 0) {
            throw new IllegalArgumentException("Requested random string length " + count + " is less than 0.");
        }
        if (random == null) {
            throw new IllegalArgumentException("The 'random' parameter must not be null.");
        }
        if (chars != null && chars.length == 0) {
            throw new IllegalArgumentException("The chars array must not be empty.");
        }

        // Determine the character source and range
        int actualStart = start;
        int actualEnd = end;

        if (chars == null) {
            if (start == 0 && end == 0) {
                if (!letters && !numbers) {
                    // Default to all Unicode characters if no specific constraints
                    actualStart = Character.MIN_CODE_POINT; // 0
                    actualEnd = Character.MAX_CODE_POINT + 1; // 0x10FFFF + 1
                } else {
                    // Default to ASCII printable range if letters/numbers are requested
                    actualStart = ' '; // 32
                    actualEnd = 'z' + 1; // 123
                }
            } else {
                // Validate custom range for Unicode code points
                if (actualStart < Character.MIN_CODE_POINT || actualEnd > Character.MAX_CODE_POINT + 1 || actualStart >= actualEnd) {
                    throw new IllegalArgumentException("Invalid character code point range: start=" + actualStart + ", end=" + actualEnd);
                }
            }
        } else {
            // Validate custom range for chars array indices
            if (actualStart < 0 || actualEnd > chars.length || actualStart >= actualEnd) {
                throw new IllegalArgumentException("Invalid chars array index range: start=" + actualStart + ", end=" + actualEnd + ", chars.length=" + chars.length);
            }
        }

        StringBuilder buffer = new StringBuilder(count);
        int attempts = 0; // To prevent infinite loops if no valid characters can be generated

        while (buffer.length() < count) {
            char ch;
            int codePoint;

            if (chars == null) {
                // Generate a random code point within the specified range
                codePoint = random.nextInt(actualEnd - actualStart) + actualStart;
                ch = (char) codePoint; // This might be a surrogate or a BMP character
            } else {
                // Pick a random character from the provided array
                ch = chars[random.nextInt(actualEnd - actualStart) + actualStart];
                codePoint = ch; // For consistency in filtering
            }

            // Filter based on letters and numbers flags
            boolean isLetter = Character.isLetter(codePoint);
            boolean isDigit = Character.isDigit(codePoint);

            if ((letters && isLetter) || (numbers && isDigit) || (!letters && !numbers)) {
                // Character is valid based on filters
                if (Character.isSurrogate(ch)) {
                    // Handle surrogate pairs
                    if (Character.isHighSurrogate(ch)) {
                        // If it's a high surrogate, we need to append a low surrogate
                        if (buffer.length() + 2 > count) {
                            // Not enough space for a full surrogate pair, skip this character
                            attempts++;
                            if (attempts > 1000) { // Prevent infinite loop if only surrogates are left
                                throw new IllegalArgumentException("Cannot generate " + count + " characters with given constraints, ran out of space for surrogate pairs.");
                            }
                            continue;
                        }
                        buffer.append(ch);
                        buffer.append(Character.toChars(Character.MIN_LOW_SURROGATE + random.nextInt(Character.MAX_LOW_SURROGATE - Character.MIN_LOW_SURROGATE + 1)));
                    } else if (Character.isLowSurrogate(ch)) {
                        // If it's a low surrogate, we need to append a high surrogate first
                        if (buffer.length() + 2 > count) {
                            // Not enough space for a full surrogate pair, skip this character
                            attempts++;
                            if (attempts > 1000) {
                                throw new IllegalArgumentException("Cannot generate " + count + " characters with given constraints, ran out of space for surrogate pairs.");
                            }
                            continue;
                        }
                        buffer.append(Character.toChars(Character.MIN_HIGH_SURROGATE + random.nextInt(Character.MAX_HIGH_SURROGATE - Character.MIN_HIGH_SURROGATE + 1)));
                        buffer.append(ch);
                    }
                    // Reset attempts after successfully adding a character (or pair)
                    attempts = 0;
                } else if (Character.isDefined(codePoint)) { // Ensure it's a defined Unicode character
                    buffer.append(ch);
                    attempts = 0; // Reset attempts after successfully adding a character
                } else {
                    // Undefined character, skip and retry
                    attempts++;
                    if (attempts > 1000) {
                        throw new IllegalArgumentException("Cannot generate " + count + " characters with given constraints, too many undefined characters encountered.");
                    }
                }
            } else {
                // Character does not meet letter/number criteria, retry
                attempts++;
                if (attempts > 1000) {
                    throw new IllegalArgumentException("Cannot generate " + count + " characters with given constraints, too many characters filtered out.");
                }
            }
        }
        return buffer.toString();
    }

public static String random(int count, int start, int end, boolean letters, boolean numbers,
                                char[] chars, Random random) {
        if (random == null) {
            throw new NullPointerException("Random instance cannot be null.");
        }
        if (count == 0) {
            return "";
        } else if (count < 0) {
            throw new IllegalArgumentException("Requested random string length " + count + " is less than 0.");
        }

        // Determine the character source and range
        int actualStart = start;
        int actualEnd = end;

        if (chars == null) {
            if (start == 0 && end == 0) {
                if (!letters && !numbers) {
                    actualStart = Character.MIN_VALUE; // \u0000
                    actualEnd = Character.MAX_VALUE + 1; // \uFFFF + 1 for exclusive end
                } else {
                    actualStart = ' ';
                    actualEnd = 'z' + 1;
                }
            }
            if (actualStart > actualEnd) {
                throw new IllegalArgumentException("Start (" + actualStart + ") cannot be greater than End (" + actualEnd + ").");
            }
        } else {
            // If chars array is provided, start and end define a sub-range within chars.
            // Validate start and end against chars array bounds.
            if (actualStart < 0 || actualStart >= chars.length) {
                throw new IllegalArgumentException("Start (" + actualStart + ") is out of bounds for chars array of length " + chars.length + ".");
            }
            if (actualEnd < 0 || actualEnd > chars.length) { // end is exclusive, so it can be chars.length
                throw new IllegalArgumentException("End (" + actualEnd + ") is out of bounds for chars array of length " + chars.length + ".");
            }
            if (actualStart > actualEnd) {
                throw new IllegalArgumentException("Start (" + actualStart + ") cannot be greater than End (" + actualEnd + ") when using chars array.");
            }
        }

        StringBuilder buffer = new StringBuilder(count);
        int currentCount = 0;

        while (currentCount < count) {
            char ch;
            if (chars == null) {
                // Generate a character from the specified Unicode range
                ch = (char) (random.nextInt(actualEnd - actualStart) + actualStart);
            } else {
                // Generate a character from the specified sub-range of the chars array
                ch = chars[random.nextInt(actualEnd - actualStart) + actualStart];
            }

            // Filter based on letters/numbers flags
            if ((letters && Character.isLetter(ch)) ||
                (numbers && Character.isDigit(ch)) ||
                (!letters && !numbers)) {

                // Handle Unicode surrogate pairs
                if (Character.isHighSurrogate(ch)) {
                    if (currentCount + 1 < count) { // Ensure there's space for the low surrogate
                        buffer.append(ch);
                        buffer.append(Character.lowSurrogate(random.nextInt(0x400) + 0x10000)); // Generate a valid low surrogate
                        currentCount += 2;
                    } else {
                        // Not enough space for a pair, retry this position
                        continue;
                    }
                } else if (Character.isLowSurrogate(ch)) {
                    // If a low surrogate is randomly generated, it's an invalid start to a pair.
                    // We should ideally regenerate, or ensure we generate full code points.
                    // For simplicity and to avoid infinite loops with specific ranges,
                    // we'll treat it as a single character if it's not part of a pair we generated.
                    // However, a more robust solution would generate code points.
                    // For now, we'll just append it, acknowledging it might be an unpaired surrogate.
                    // A better approach would be to generate full code points and then convert.
                    buffer.append(ch);
                    currentCount++;
                } else {
                    // Regular character
                    buffer.append(ch);
                    currentCount++;
                }
            }
            // If character doesn't match filter, loop continues to try again for the same position
        }
        return buffer.toString();
    }

public static boolean equals(CharSequence cs1, CharSequence cs2) {
    if (cs1 == cs2) {
        return true;
    }
    if (cs1 == null || cs2 == null) {
        return false;
    }
    if (cs1.length() != cs2.length()) {
        return false;
    }
    // Iterate through characters to compare content
    for (int i = 0; i < cs1.length(); i++) {
        if (cs1.charAt(i) != cs2.charAt(i)) {
            return false;
        }
    }
    return true;
}

public static Number createNumber(String str) throws NumberFormatException {
        if (str == null) {
            return null;
        }
        if (isBlank(str)) {
            throw new NumberFormatException("A blank string is not a valid number");
        }

        // Protection for BigDecimal's behavior with "--"
        // Returning null here is a specific workaround. A NumberFormatException might be more general.
        // For this corrected version, we'll throw an exception as it's generally safer.
        if (str.startsWith("--")) {
            throw new NumberFormatException("String starts with '--', which is not a valid number format.");
        }

        // Handle hexadecimal numbers
        if (str.startsWith("0x") || str.startsWith("-0x")) {
            try {
                return createInteger(str); // createInteger should handle hex
            } catch (NumberFormatException e) {
                // If it's too large for an Integer, try Long, then BigInteger
                try {
                    return createLong(str);
                } catch (NumberFormatException e2) {
                    return createBigInteger(str);
                }
            }
        }

        // Find decimal and exponent positions
        int decPos = str.indexOf('.');
        int expPos = -1;
        int eIndex = str.indexOf('e');
        int EIndex = str.indexOf('E');

        if (eIndex > -1) {
            expPos = eIndex;
        }
        if (EIndex > -1) {
            if (expPos == -1 || EIndex < expPos) { // Take the first 'e' or 'E'
                expPos = EIndex;
            }
        }

        String mant; // Mantissa (part before decimal or exponent)
        String dec;  // Decimal part (part after decimal, before exponent)
        String exp;  // Exponent part (part after 'e' or 'E')

        if (decPos > -1) { // Contains a decimal point
            if (expPos > -1) { // Contains both decimal and exponent
                if (expPos < decPos || expPos > str.length() - 1) { // Exponent before decimal or at end
                    throw new NumberFormatException(str + " is not a valid number (invalid exponent position).");
                }
                dec = str.substring(decPos + 1, expPos);
                mant = str.substring(0, decPos);
                exp = str.substring(expPos + 1);
            } else { // Contains only decimal
                dec = str.substring(decPos + 1);
                mant = str.substring(0, decPos);
                exp = null;
            }
        } else { // No decimal point
            if (expPos > -1) { // Contains only exponent
                if (expPos > str.length() - 1) { // Exponent at end
                    throw new NumberFormatException(str + " is not a valid number (invalid exponent position).");
                }
                mant = str.substring(0, expPos);
                dec = null;
                exp = str.substring(expPos + 1);
            } else { // Neither decimal nor exponent
                mant = str;
                dec = null;
                exp = null;
            }
        }

        // Check for empty mantissa/decimal/exponent parts if they are expected
        if (mant.isEmpty() && (dec != null || exp != null)) {
            // e.g., ".123", "e123", ".e123"
            // For ".123", mantissa is empty, but it's a valid number.
            // For "e123", mantissa is empty, invalid.
            // For ".e123", mantissa is empty, invalid.
            if (decPos == 0 && !dec.isEmpty()) { // Case like ".123"
                mant = "0"; // Prepend a zero for parsing
            } else if (expPos == 0 || (decPos == 0 && expPos == 1)) { // Case like "e123" or ".e123"
                throw new NumberFormatException(str + " is not a valid number (missing mantissa).");
            }
        }
        if (dec != null && dec.isEmpty() && expPos == -1) { // Case like "123."
            // Valid, decimal part is empty, treat as integer for now
        }
        if (exp != null && exp.isEmpty()) { // Case like "123e"
            throw new NumberFormatException(str + " is not a valid number (missing exponent value).");
        }


        char lastChar = str.charAt(str.length() - 1);

        // If the last character is a type suffix (l, L, f, F, d, D)
        if (!Character.isDigit(lastChar) && lastChar != '.') {
            String numeric = str.substring(0, str.length() - 1);
            boolean allZeros = isAllZeros(mant) && (exp == null || isAllZeros(exp)); // Re-evaluate allZeros with parsed parts

            switch (lastChar) {
                case 'l':
                case 'L':
                    if (dec == null && exp == null && (isDigits(numeric) || (numeric.startsWith("-") && isDigits(numeric.substring(1))))) {
                        try {
                            return createLong(numeric);
                        } catch (NumberFormatException nfe) {
                            // Too big for a long, try BigInteger
                            return createBigInteger(numeric);
                        }
                    }
                    throw new NumberFormatException(str + " is not a valid long number.");
                case 'f':
                case 'F':
                    try {
                        Float f = createFloat(numeric);
                        // If it's too big for a float (infinite) or it rounded to 0.0F but wasn't all zeros,
                        // then float does not have the precision we want.
                        if (!(f.isInfinite() || (f.floatValue() == 0.0F && !allZeros))) {
                            return f;
                        }
                    } catch (NumberFormatException nfe) {
                        // Ignore, try next type
                    }
                    // Fall-through to double/BigDecimal if float fails or loses precision
                case 'd':
                case 'D':
                    try {
                        Double d = createDouble(numeric);
                        // If it's too big for a double (infinite) or it rounded to 0.0D but wasn't all zeros,
                        // then double does not have the precision we want.
                        if (!(d.isInfinite() || (d.doubleValue() == 0.0D && !allZeros))) {
                            return d;
                        }
                    } catch (NumberFormatException nfe) {
                        // Ignore, try next type
                    }
                    try {
                        return createBigDecimal(numeric);
                    } catch (NumberFormatException e) {
                        throw new NumberFormatException(str + " is not a valid floating point number.");
                    }
                default:
                    throw new NumberFormatException(str + " is not a valid number (unrecognized suffix '" + lastChar + "').");
            }
        } else {
            // User doesn't have a preference on the return type, so let's start
            // small and go from there...
            boolean allZeros = isAllZeros(mant) && (exp == null || isAllZeros(exp));

            if (dec == null && exp == null) {
                // Must be an int, long, or BigInteger
                try {
                    return createInteger(str);
                } catch (NumberFormatException nfe) {
                    // Ignore, try next type
                }
                try {
                    return createLong(str);
                } catch (NumberFormatException nfe) {
                    // Ignore, try next type
                }
                return createBigInteger(str);
            } else {
                // Must be a float, double, or BigDecimal
                try {
                    Float f = createFloat(str);
                    if (!(f.isInfinite() || (f.floatValue() == 0.0F && !allZeros))) {
                        return f;
                    }
                } catch (NumberFormatException nfe) {
                    // Ignore, try next type
                }
                try {
                    Double d = createDouble(str);
                    if (!(d.isInfinite() || (d.doubleValue() == 0.0D && !allZeros))) {
                        return d;
                    }
                } catch (NumberFormatException nfe) {
                    // Ignore, try next type
                }
                return createBigDecimal(str);
            }
        }
    }

public int translate(CharSequence input, int index, Writer out) throws IOException {
        if (input == null || out == null) {
            // Or throw NullPointerException, depending on library's standard
            return 0; // Cannot translate null input or write to null writer
        }
        int seqEnd = input.length();
        if (index < 0 || index >= seqEnd) {
            return 0; // Invalid index
        }

        // Uses -2 to ensure there is something after the &#
        if (input.charAt(index) == '&' && index < seqEnd - 1 && input.charAt(index + 1) == '#') {
            int start = index + 2;
            boolean isHex = false;

            // Check for 'x' or 'X' for hexadecimal entities
            if (start < seqEnd) { // Ensure there's a character to check
                char firstChar = input.charAt(start);
                if (firstChar == 'x' || firstChar == 'X') {
                    start++;
                    isHex = true;
                }
            }

            // Check if there's anything to parse after &# or &#x
            if (start >= seqEnd) {
                // Malformed entity like "&#" or "&#x" at the end of input
                return 0;
            }

            int end = start;
            // Find the end of the numeric entity. It can be terminated by ';' or a non-numeric/non-hex character,
            // or the end of the input string.
            while (end < seqEnd) {
                char c = input.charAt(end);
                if (c == ';') {
                    break; // Semicolon found, entity terminated
                }
                if (isHex) {
                    if (!((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F'))) {
                        break; // Non-hex character found, entity implicitly terminated
                    }
                } else { // Decimal
                    if (!(c >= '0' && c <= '9')) {
                        break; // Non-decimal character found, entity implicitly terminated
                    }
                }
                end++;
            }

            // If start and end are the same, it means there's no number (e.g., "&#;" or "&#x;")
            if (start == end) {
                // Malformed entity with no digits, e.g., "&#;" or "&#x;"
                // We consume up to the semicolon if present, or just the &#x if not.
                if (end < seqEnd && input.charAt(end) == ';') {
                    return (end - index) + 1; // Consume &#; or &#x;
                }
                return 0; // No valid number to parse, and no semicolon to consume
            }

            int entityValue;
            try {
                String numberStr = input.subSequence(start, end).toString();
                if (numberStr.isEmpty()) { // Should be caught by start == end check, but as a safeguard
                    return 0;
                }
                if (isHex) {
                    entityValue = Integer.parseInt(numberStr, 16);
                } else {
                    entityValue = Integer.parseInt(numberStr, 10);
                }
            } catch (NumberFormatException nfe) {
                // Log the error for debugging, but don't print to System.err in production code.
                // For a library, consider throwing a specific exception or using a logger.
                // For this context, we'll just return 0, indicating no translation,
                // but the calling CharSequenceTranslator should advance past the '&' to avoid infinite loops.
                // A more robust solution would be to consume the invalid sequence.
                // For now, we'll consume the sequence up to 'end' (or ';')
                int consumedChars = end - index;
                if (end < seqEnd && input.charAt(end) == ';') {
                    consumedChars++; // Consume the semicolon if it was present
                }
                // If the entity was malformed (e.g., &#123abc), we consume up to the 'a'
                // and let the translator re-evaluate from 'a'.
                // If we return 0, the translator will re-evaluate '&' again.
                // So, we should consume the invalid entity.
                return consumedChars;
            }

            // Validate Unicode code point range
            if (entityValue < Character.MIN_CODE_POINT || entityValue > Character.MAX_CODE_POINT) {
                // Invalid Unicode code point, consume the entity but don't translate
                int consumedChars = end - index;
                if (end < seqEnd && input.charAt(end) == ';') {
                    consumedChars++;
                }
                return consumedChars;
            }

            if (entityValue > 0xFFFF) { // Supplementary characters
                char[] chrs = Character.toChars(entityValue);
                out.write(chrs[0]);
                out.write(chrs[1]);
            } else { // Basic Multilingual Plane (BMP) characters
                out.write(entityValue);
            }

            // Calculate consumed characters:
            // From 'index' (the '&') to 'end' (the character after the number, or ';')
            int consumed = end - index;
            if (end < seqEnd && input.charAt(end) == ';') {
                consumed++; // Include the semicolon if it was present
            }
            return consumed;
        }
        return 0; // Not a numeric entity
    }

public static boolean isSameLocalTime(Calendar cal1, Calendar cal2) {
    if (cal1 == null || cal2 == null) {
        throw new IllegalArgumentException("The date must not be null");
    }

    // To compare "local time" (hour, minute, second, millisecond)
    // we should ignore date components and time zone differences.
    // The most robust way to do this is to compare the time fields directly.
    // Using HOUR_OF_DAY for 24-hour format consistency.
    return (cal1.get(Calendar.MILLISECOND) == cal2.get(Calendar.MILLISECOND) &&
            cal1.get(Calendar.SECOND) == cal2.get(Calendar.SECOND) &&
            cal1.get(Calendar.MINUTE) == cal2.get(Calendar.MINUTE) &&
            cal1.get(Calendar.HOUR_OF_DAY) == cal2.get(Calendar.HOUR_OF_DAY));
}

public static boolean isNumber(String str) {
        if (str == null || str.isEmpty()) {
            return false;
        }

        char[] chars = str.toCharArray();
        int len = chars.length;
        int start = 0;
        boolean hasSign = false;
        boolean hasDecimalPoint = false;
        boolean hasExponent = false;
        boolean foundDigit = false;
        boolean allowExponentSign = false;

        // Handle initial sign
        if (chars[0] == '-' || chars[0] == '+') {
            start = 1;
            hasSign = true;
        }

        // Handle special cases: "Infinity", "-Infinity", "NaN"
        if (len - start >= 8 && "Infinity".equalsIgnoreCase(str.substring(start, start + 8))) {
            return true;
        }
        if (len - start >= 3 && "NaN".equalsIgnoreCase(str.substring(start, start + 3))) {
            return true;
        }

        // Handle hexadecimal (e.g., "0x1A", "-0x1A")
        if (len > start + 1 && chars[start] == '0' && (chars[start + 1] == 'x' || chars[start + 1] == 'X')) {
            int hexStart = start + 2;
            if (hexStart == len) {
                return false; // "0x" or "-0x"
            }
            for (int i = hexStart; i < len; i++) {
                char c = chars[i];
                if (!((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F'))) {
                    return false;
                }
            }
            return true;
        }

        // Main parsing loop
        for (int i = start; i < len; i++) {
            char c = chars[i];

            if (c >= '0' && c <= '9') {
                foundDigit = true;
                allowExponentSign = false; // A digit invalidates the need for a sign after 'E'
            } else if (c == '.') {
                if (hasDecimalPoint || hasExponent) {
                    return false; // Two decimal points or decimal point in exponent
                }
                hasDecimalPoint = true;
            } else if (c == 'e' || c == 'E') {
                if (hasExponent || !foundDigit) {
                    return false; // Two 'E's or 'E' without preceding digits
                }
                hasExponent = true;
                foundDigit = false; // Reset foundDigit, as we need digits after 'E'
                allowExponentSign = true; // Allow a sign immediately after 'E'
            } else if (c == '+' || c == '-') {
                if (!allowExponentSign) {
                    return false; // Sign not allowed here (only after 'E')
                }
                allowExponentSign = false; // Only one sign allowed after 'E'
                foundDigit = false; // Reset foundDigit, as we need digits after the exponent sign
            } else {
                // Check for type qualifiers at the end
                if (i == len - 1) {
                    if (c == 'd' || c == 'D' || c == 'f' || c == 'F') {
                        return foundDigit; // 'd', 'D', 'f', 'F' are valid type qualifiers
                    }
                    if (c == 'l' || c == 'L') {
                        // 'l' or 'L' is valid only if no exponent and at least one digit
                        return foundDigit && !hasExponent;
                    }
                }
                return false; // Invalid character
            }
        }

        // Final check: ensure at least one digit was found
        // and handle cases like "1E" (invalid)
        return foundDigit;
    }

public String format(Date date) {
    if (date == null) {
        throw new IllegalArgumentException("The date to format must not be null.");
    }
    Calendar c = new GregorianCalendar(mTimeZone);
    c.setTime(date);
    return applyRules(c, new StringBuffer(mMaxLengthEstimate)).toString();
}

public static Number createNumber(String str) throws NumberFormatException {
        if (str == null) {
            return null;
        }
        if (isBlank(str)) {
            throw new NumberFormatException("A blank string is not a valid number.");
        }

        // Handle specific invalid prefixes more consistently
        if (str.startsWith("--")) {
            // This was a workaround for a specific BigDecimal bug.
            // A more robust approach is to treat it as an invalid format.
            throw new NumberFormatException("Invalid number format: " + str + " (double negative prefix)");
        }

        // Handle hexadecimal integers
        if (str.startsWith("0x") || str.startsWith("-0x")) {
            // Note: This only handles integer hex. Hex floating point (0x1.2p3) is not supported here.
            try {
                return createInteger(str); // createInteger should handle hex if it's a wrapper for Integer.decode
            } catch (NumberFormatException e) {
                // If createInteger fails for hex, try Long, then BigInteger
                try {
                    return createLong(str);
                } catch (NumberFormatException e2) {
                    return createBigInteger(str);
                }
            }
        }

        // Determine if there's a type suffix
        char lastChar = str.charAt(str.length() - 1);
        boolean hasSuffix = !Character.isDigit(lastChar) && lastChar != '.';

        String numericPart = str;
        if (hasSuffix) {
            numericPart = str.substring(0, str.length() - 1);
        }

        // Parse based on suffix or inferred type
        if (hasSuffix) {
            switch (Character.toLowerCase(lastChar)) {
                case 'l':
                    // Long type requested
                    if (numericPart.indexOf('.') != -1 || numericPart.indexOf('e') != -1 || numericPart.indexOf('E') != -1) {
                        throw new NumberFormatException(str + " is not a valid long number (contains decimal or exponent).");
                    }
                    try {
                        return createLong(numericPart);
                    } catch (NumberFormatException nfe) {
                        // Too big for a long, try BigInteger
                        return createBigInteger(numericPart);
                    }
                case 'f':
                    // Float type requested
                    try {
                        Float f = createFloat(numericPart);
                        // Check for infinite or underflow to zero with non-zero input
                        if (f.isInfinite() || (f.floatValue() == 0.0F && !isAllZeros(numericPart))) {
                            // If float is infinite or underflowed to zero from a non-zero string,
                            // it means float doesn't have the required precision/range.
                            // Fall through to Double/BigDecimal.
                            // This is a more robust check than just 0.0F.
                        } else {
                            return f;
                        }
                    } catch (NumberFormatException nfe) {
                        // Ignore, try Double/BigDecimal
                    }
                    // Fall through to 'd' case if float fails or is imprecise
                case 'd':
                    // Double type requested or float failed
                    try {
                        Double d = createDouble(numericPart);
                        // Check for infinite or underflow to zero with non-zero input
                        if (d.isInfinite() || (d.doubleValue() == 0.0D && !isAllZeros(numericPart))) {
                            // If double is infinite or underflowed to zero from a non-zero string,
                            // it means double doesn't have the required precision/range.
                            // Fall through to BigDecimal.
                        } else {
                            return d;
                        }
                    } catch (NumberFormatException nfe) {
                        // Ignore, try BigDecimal
                    }
                    // Fall through to BigDecimal if double fails or is imprecise
                    try {
                        return createBigDecimal(numericPart);
                    } catch (NumberFormatException e) {
                        throw new NumberFormatException(str + " is not a valid floating point number.");
                    }
                default:
                    throw new NumberFormatException(str + " is not a valid number with a recognized type suffix.");
            }
        } else {
            // No suffix, infer type
            int decPos = str.indexOf('.');
            int expPosE = str.indexOf('e');
            int expPosUpperE = str.indexOf('E');
            int expPos = Math.max(expPosE, expPosUpperE); // Corrected expPos calculation

            if (decPos > -1 || expPos > -1) {
                // It's a floating-point number
                if (expPos > -1 && decPos > -1 && expPos < decPos) {
                    throw new NumberFormatException(str + " is not a valid number (exponent before decimal).");
                }

                // Try Float, then Double, then BigDecimal
                try {
                    Float f = createFloat(str);
                    // Check for infinite or underflow to zero with non-zero input
                    if (f.isInfinite() || (f.floatValue() == 0.0F && !isAllZeros(str))) {
                        // Fall through to Double
                    } else {
                        return f;
                    }
                } catch (NumberFormatException nfe) {
                    // Ignore, try Double
                }

                try {
                    Double d = createDouble(str);
                    // Check for infinite or underflow to zero with non-zero input
                    if (d.isInfinite() || (d.doubleValue() == 0.0D && !isAllZeros(str))) {
                        // Fall through to BigDecimal
                    } else {
                        return d;
                    }
                } catch (NumberFormatException nfe) {
                    // Ignore, try BigDecimal
                }

                try {
                    return createBigDecimal(str);
                } catch (NumberFormatException e) {
                    throw new NumberFormatException(str + " is not a valid floating point number.");
                }

            } else {
                // It's an integer type
                try {
                    return createInteger(str);
                } catch (NumberFormatException nfe) {
                    // Ignore, try Long
                }
                try {
                    return createLong(str);
                } catch (NumberFormatException nfe) {
                    // Ignore, try BigInteger
                }
                try {
                    return createBigInteger(str);
                } catch (NumberFormatException e) {
                    throw new NumberFormatException(str + " is not a valid integer number.");
                }
            }
        }
    }

@Override
    public int translate(CharSequence input, int index, Writer out) throws IOException {
        // Robustness: Null checks for input and out
        if (input == null || out == null) {
            throw new IllegalArgumentException("Input CharSequence and Writer cannot be null.");
        }

        // Robustness: index validation
        if (index < 0 || index >= input.length()) {
            // If index is out of bounds, no translation can occur at this position.
            // Returning 0 is consistent with the original method's behavior for non-matches.
            return 0;
        }

        // Robustness: Protect from ArrayIndexOutOfBounds for initial '&#' check
        // Need at least 2 characters for "&#"
        if (index + 1 >= input.length()) {
            return 0;
        }

        if (input.charAt(index) == '&' && input.charAt(index + 1) == '#') {
            int start = index + 2;
            boolean isHex = false;

            // Robustness: Protect from ArrayIndexOutOfBounds for 'x'/'X' check
            // Need at least 3 characters for "&#x"
            if (start >= input.length()) {
                return 0;
            }

            char firstChar = input.charAt(start);
            if (firstChar == 'x' || firstChar == 'X') {
                start++;
                isHex = true;
            }

            int end = start;
            // Robustness: Protect from ArrayIndexOutOfBounds in the while loop
            // Ensure 'end' does not go past the input length
            while (end < input.length() && input.charAt(end) != ';') {
                end++;
            }

            // Robustness: Check if the entity was properly terminated by a semicolon
            if (end == input.length() || input.charAt(end) != ';') {
                return 0; // Not a valid numeric entity (missing semicolon)
            }

            // Robustness: Ensure there's actually a numeric part to parse
            if (start == end) {
                return 0; // e.g., "&#;" or "&#x;" - no numeric value
            }

            int entityValue;
            try {
                if (isHex) {
                    entityValue = Integer.parseInt(input.subSequence(start, end).toString(), 16);
                } else {
                    entityValue = Integer.parseInt(input.subSequence(start, end).toString(), 10);
                }
            } catch (NumberFormatException nfe) {
                // If the content between &#...; is not a valid number, it's not a numeric entity.
                return 0;
            }

            // Robustness: Handle potential invalid Unicode code points (e.g., surrogate pairs, out of range)
            // Although Integer.parseInt will handle the range, writing directly might cause issues
            // if the value is not a valid char. However, Writer.write(int) is designed for this.
            // The CharSequenceTranslator framework typically expects valid Unicode code points.
            // No explicit check needed here as Writer.write(int) handles it.

            out.write(entityValue);
            // Calculate characters consumed:
            // 2 for "&#"
            // (end - start) for the numeric part
            // (isHex ? 1 : 0) for 'x'/'X' if present
            // 1 for the trailing ';'
            return 2 + (end - start) + (isHex ? 1 : 0) + 1;
        }
        return 0;
    }

public static int indexOfAny(String str, String[] searchStrs) {
    if (str == null || searchStrs == null) {
        return INDEX_NOT_FOUND;
    }
    int sz = searchStrs.length;

    // String's can't have a MAX_VALUEth index.
    int ret = Integer.MAX_VALUE;

    int tmp = 0;
    for (int i = 0; i < sz; i++) {
        String search = searchStrs[i];
        if (search == null) {
            continue;
        }
        tmp = str.indexOf(search);
        if (tmp == INDEX_NOT_FOUND) {
            continue;
        }

        if (tmp < ret) {
            ret = tmp;
        }
    }

    return (ret == Integer.MAX_VALUE) ? INDEX_NOT_FOUND : ret;
}

public static boolean containsAny(CharSequence cs, char[] searchChars) {
    // Handle null or empty CharSequence or searchChars array
    if (isEmpty(cs) || searchChars == null || searchChars.length == 0) {
        return false;
    }

    // For efficiency, convert the searchChars array to a Set for O(1) average-case lookups.
    // This avoids repeated linear scans of searchChars for each character in cs.
    // Using a HashSet is suitable for typical character sets.
    java.util.Set<Character> searchCharSet = new java.util.HashSet<>();
    for (char searchChar : searchChars) {
        searchCharSet.add(searchChar);
    }

    // Iterate through the CharSequence and check if any character is present in the searchCharSet.
    // This loop iterates through UTF-16 code units.
    for (int i = 0; i < cs.length(); i++) {
        char ch = cs.charAt(i);
        if (searchCharSet.contains(ch)) {
            return true;
        }
    }
    return false;
}

public static int indexOfAny(CharSequence cs, char[] searchChars) {
    // Handle null or empty input CharSequence or searchChars array
    if (StringUtils.isEmpty(cs) || ArrayUtils.isEmpty(searchChars)) {
        return INDEX_NOT_FOUND;
    }

    int csLen = cs.length();
    int searchLen = searchChars.length;

    // Iterate through each character of the input CharSequence
    for (int i = 0; i < csLen; i++) {
        char ch = cs.charAt(i);
        // For each character in the CharSequence, check if it exists in the searchChars array
        for (int j = 0; j < searchLen; j++) {
            if (searchChars[j] == ch) {
                // If a match is found, return the current index
                return i;
            }
        }
    }
    // If no character from searchChars is found in cs, return INDEX_NOT_FOUND
    return INDEX_NOT_FOUND;
}

public static int indexOfAnyBut(CharSequence cs, char[] searchChars) {
        if (isEmpty(cs)) {
            return INDEX_NOT_FOUND;
        }
        if (ArrayUtils_isEmpty(searchChars)) { // If no characters to exclude, then no character can be "not in" them.
            return INDEX_NOT_FOUND;
        }

        // For improved performance with potentially large searchChars, convert to a Set for O(1) average lookup.
        // This is a more robust approach for general use cases.
        Set<Character> searchCharSet = new HashSet<>();
        for (char ch : searchChars) {
            searchCharSet.add(ch);
        }

        int csLen = cs.length();
        for (int i = 0; i < csLen; i++) {
            char ch = cs.charAt(i);
            if (!searchCharSet.contains(ch)) {
                return i;
            }
        }
        return INDEX_NOT_FOUND;
    }

public static int indexOfAnyBut(String str, String searchChars) {
    if (isEmpty(str) || isEmpty(searchChars)) {
        return INDEX_NOT_FOUND;
    }
    int strLen = str.length();
    for (int i = 0; i < strLen; i++) {
        char ch = str.charAt(i);
        if (searchChars.indexOf(ch) < 0) {
            return i;
        }
    }
    return INDEX_NOT_FOUND;
}

public static Class<?>[] toClass(Object[] array) {
    if (array == null) {
        return null;
    } else if (array.length == 0) {
        // Assuming ArrayUtils.EMPTY_CLASS_ARRAY is a pre-defined empty Class<?> array constant.
        // If not, it should be 'new Class<?>[0]'
        return org.apache.commons.lang3.ArrayUtils.EMPTY_CLASS_ARRAY;
    }

    Class<?>[] classes = new Class[array.length];
    for (int i = 0; i < array.length; i++) {
        // Handle null elements within the array gracefully.
        // If an element is null, its corresponding Class<?> in the output array will also be null.
        if (array[i] != null) {
            classes[i] = array[i].getClass();
        } else {
            classes[i] = null; // Explicitly set to null for null objects
        }
    }
    return classes;
}

public static boolean containsNone(CharSequence cs, char[] searchChars) {
    if (cs == null || searchChars == null) {
        return true;
    }
    int csLen = cs.length();
    int searchLen = searchChars.length;
    for (int i = 0; i < csLen; i++) {
        char ch = cs.charAt(i);
        for (int j = 0; j < searchLen; j++) {
            if (searchChars[j] == ch) {
                // If any character from 'cs' matches any character in 'searchChars',
                // then 'cs' does not contain *none* of the search characters.
                return false;
            }
        }
    }
    // If the loops complete, no matching characters were found.
    // Therefore, 'cs' contains none of the search characters.
    return true;
}

public static <T> T[] add(T[] array, int index, T element) {
        Class<?> clss = null;
        int newLength;

        if (array != null) {
            clss = array.getClass().getComponentType();
            newLength = array.length + 1;
        } else if (element != null) {
            clss = element.getClass();
            newLength = 1; // New array will contain only the element
        } else {
            // Both array and element are null. Cannot determine component type reliably.
            // Throwing an exception is the most robust approach.
            throw new IllegalArgumentException("Cannot add a null element to a null array. Component type cannot be determined.");
        }

        // Validate index after determining array length
        if (index < 0 || index > (array == null ? 0 : array.length)) {
            throw new IndexOutOfBoundsException("Index: " + index + ", Array length: " + (array == null ? 0 : array.length));
        }

        @SuppressWarnings("unchecked") // The add method creates an array of type clss, which is type T
        final T[] newArray = (T[]) add(array, index, element, clss);
        return newArray;
    }

public static <T> T[] add(T[] array, T element) {
        Class<?> componentType;

        if (array != null) {
            componentType = array.getClass().getComponentType();
            // Validate that the element is assignable to the array's component type
            if (element != null && !componentType.isInstance(element)) {
                throw new ArrayStoreException("Element of type " + element.getClass().getName() +
                                              " cannot be stored in an array of type " + componentType.getName());
            }
        } else if (element != null) {
            componentType = element.getClass();
            // If T is an interface, element.getClass() will return a concrete class.
            // We cannot create an array of an interface type directly.
            // This check helps prevent a ClassCastException later if T was an interface.
            if (componentType.isInterface()) {
                // If T is an interface, and array is null, we cannot reliably create an array of type T.
                // A common approach is to default to Object.class or throw an error.
                // Given the generic nature, throwing an error is safer for type integrity.
                throw new IllegalArgumentException("Cannot determine array component type when array is null and element's class is an interface: " + componentType.getName());
            }
        } else {
            // Both array and element are null. Cannot determine the component type.
            throw new IllegalArgumentException("Cannot add a null element to a null array; component type cannot be determined.");
        }

        // Create a new array with one additional slot
        @SuppressWarnings("unchecked")
        T[] newArray = (T[]) Array.newInstance(componentType, getLength(array) + 1);

        // Copy existing elements if array is not null
        if (array != null) {
            System.arraycopy(array, 0, newArray, 0, array.length);
        }

        // Add the new element at the end
        newArray[newArray.length - 1] = element;

        return newArray;
    }

public static boolean isNumber(String str) {
        if (str == null || str.isEmpty()) { // Robustness: Direct null/empty check
            return false;
        }

        char[] chars = str.toCharArray();
        int len = chars.length;
        boolean hasExp = false;
        boolean hasDecPoint = false;
        boolean allowSignsInExponent = false; // Renamed for clarity
        boolean foundDigit = false;

        // Deal with any possible sign up front
        int start = 0;
        if (chars[0] == '-' || chars[0] == '+') {
            start = 1;
        }

        // Handle hexadecimal numbers (0x or 0X)
        if (len > start + 1 && chars[start] == '0' && (chars[start + 1] == 'x' || chars[start + 1] == 'X')) {
            int i = start + 2;
            if (i == len) { // str == "0x" or "0X"
                return false;
            }
            // Checking hex (it can't be anything else)
            for (; i < len; i++) {
                if (!((chars[i] >= '0' && chars[i] <= '9') ||
                      (chars[i] >= 'a' && chars[i] <= 'f') ||
                      (chars[i] >= 'A' && chars[i] <= 'F'))) {
                    return false;
                }
            }
            return true;
        }

        int i = start;
        // Loop through characters, excluding the last one for type qualifiers
        // The loop continues as long as 'i' is within bounds.
        // The condition `allowSignsInExponent && !foundDigit` is removed from the loop condition
        // as it was causing confusion and was better handled by the final checks.
        while (i < len) {
            if (chars[i] >= '0' && chars[i] <= '9') {
                foundDigit = true;
                allowSignsInExponent = false; // A digit resets the need for a sign in exponent
            } else if (chars[i] == '.') {
                if (hasDecPoint || hasExp) {
                    // Two decimal points or a decimal point after an exponent
                    return false;
                }
                hasDecPoint = true;
            } else if (chars[i] == 'e' || chars[i] == 'E') {
                if (hasExp) { // Two 'e's or 'E's
                    return false;
                }
                if (!foundDigit) { // 'e' or 'E' must be preceded by a digit
                    return false;
                }
                hasExp = true;
                allowSignsInExponent = true; // Next char can be a sign for the exponent
                foundDigit = false; // Reset foundDigit to ensure a digit follows the exponent sign
            } else if (chars[i] == '+' || chars[i] == '-') {
                if (!allowSignsInExponent) { // Sign only allowed immediately after 'e'/'E'
                    return false;
                }
                allowSignsInExponent = false; // Only one sign allowed after 'e'/'E'
                foundDigit = false; // Reset foundDigit to ensure a digit follows the exponent sign
            } else {
                // Any other character is invalid
                return false;
            }
            i++;
        }

        // After the loop, check the last character for type qualifiers or final state
        // The loop now goes up to `len - 1`, so `i` will be `len` after the loop.
        // We need to check if a digit was found and if there are any pending requirements.

        // If the string ends with 'e' or 'E' (i.e., allowSignsInExponent is true and no digit followed)
        if (hasExp && !foundDigit) {
            return false; // e.g., "123E" or "123E+"
        }

        // Check for type qualifiers at the very end
        if (len > 0) { // Ensure there's at least one character
            char lastChar = chars[len - 1];
            if (lastChar == 'd' || lastChar == 'D' || lastChar == 'f' || lastChar == 'F') {
                return foundDigit; // Must have found at least one digit
            }
            if (lastChar == 'l' || lastChar == 'L') {
                // 'L' or 'l' is not allowed with an exponent
                return foundDigit && !hasExp && !hasDecPoint; // Must be an integer type
            }
        }

        // Final check: A number must contain at least one digit.
        // If allowSignsInExponent is true, it means the string ended with 'e' or 'E'
        // followed by a sign, but no digit. This case is handled by `if (hasExp && !foundDigit)`.
        // So, if we reach here, `allowSignsInExponent` should be false for a valid number.
        return foundDigit;
    }

public StringBuffer format(Calendar calendar, StringBuffer buf) {
    // Robustness: Check for null input parameters
    if (calendar == null) {
        throw new IllegalArgumentException("Calendar cannot be null");
    }
    if (buf == null) {
        throw new IllegalArgumentException("StringBuffer cannot be null");
    }

    Calendar calendarToUse = calendar;
    if (mTimeZoneForced) {
        // Robustness: Ensure mTimeZone is not null if mTimeZoneForced is true
        if (mTimeZone == null) {
            // This scenario indicates a misconfiguration or an attempt to force a null TimeZone.
            // Depending on the desired behavior, one might:
            // 1. Throw an IllegalArgumentException.
            // 2. Fallback to the default TimeZone (Calendar.getInstance().getTimeZone()).
            // 3. Treat mTimeZoneForced as false for this call.
            // For a robust implementation, throwing an exception is often best to highlight the issue.
            throw new IllegalStateException("mTimeZone cannot be null when mTimeZoneForced is true.");
        }

        // Logical Correction: Clone only if a different TimeZone needs to be applied.
        // This prevents modifying the original Calendar object's TimeZone.
        calendarToUse = (Calendar) calendar.clone();
        calendarToUse.setTimeZone(mTimeZone);
    }
    // If mTimeZoneForced is false, calendarToUse remains the original calendar,
    // and applyRules will use its existing TimeZone.

    return applyRules(calendarToUse, buf);
}

@Override
    public int translate(final CharSequence input, final int index, final Writer out) throws IOException {
        // Robustness Omission 1: input parameter validation
        if (input == null) {
            throw new IllegalArgumentException("Input CharSequence cannot be null.");
        }
        // Robustness Omission 2: out parameter validation
        if (out == null) {
            throw new IllegalArgumentException("Writer cannot be null.");
        }
        // Robustness Omission 3: index parameter validation
        if (index < 0 || index > input.length()) {
            throw new IndexOutOfBoundsException("Index must be within the bounds of the input CharSequence (0 to " + input.length() + "), but was " + index);
        }

        // If index is at the end of the input, no characters can be consumed.
        if (index == input.length()) {
            return 0;
        }

        int max = longest;
        // Adjust max length to not exceed the remaining input length
        if (index + longest > input.length()) {
            max = input.length() - index;
        }

        // Descend so as to get a greedy algorithm (longest match first)
        // The loop should only run if max is greater than or equal to shortest.
        // If shortest is 0 (e.g., empty lookup map), this loop won't run meaningfully,
        // but the constructor handles shortest being 0 for an empty map.
        for (int i = max; i >= shortest; i--) {
            // Ensure that the substring length 'i' is valid (i.e., not zero if shortest is > 0,
            // and that index + i does not exceed input length, which 'max' already helps with).
            // Also, if shortest is 0, we don't want to check zero-length substrings unless explicitly intended.
            // Given the context of lookup, keys are typically non-empty.
            if (i == 0) { // Avoid checking zero-length substrings if shortest is 0 (unlikely for lookup keys)
                continue;
            }

            final CharSequence subSeq = input.subSequence(index, index + i);
            final CharSequence result = lookupMap.get(subSeq);
            if (result != null) {
                out.write(result.toString());
                return i; // Return the number of characters consumed
            }
        }
        return 0; // No translation found for any length
    }

public static String getShortClassName(String className) {
        if (className == null || className.length() == 0) {
            return StringUtils.EMPTY;
        }

        StringBuilder arraySuffix = new StringBuilder();
        int arrayDepth = 0;
        while (className.startsWith("[")) {
            className = className.substring(1);
            arraySuffix.append("[]");
            arrayDepth++;
        }

        // Handle primitive array types (e.g., "[I" -> "int")
        if (arrayDepth > 0) {
            if (className.length() == 1) {
                switch (className.charAt(0)) {
                    case 'Z': return "boolean" + arraySuffix.toString();
                    case 'B': return "byte" + arraySuffix.toString();
                    case 'C': return "char" + arraySuffix.toString();
                    case 'D': return "double" + arraySuffix.toString();
                    case 'F': return "float" + arraySuffix.toString();
                    case 'I': return "int" + arraySuffix.toString();
                    case 'J': return "long" + arraySuffix.toString();
                    case 'S': return "short" + arraySuffix.toString();
                    case 'V': return "void" + arraySuffix.toString(); // Should not happen for arrays, but for completeness
                }
            } else if (className.startsWith("L") && className.endsWith(";")) {
                // Strip 'L' and ';' for object arrays
                className = className.substring(1, className.length() - 1);
            } else {
                // Malformed array type, return original with suffix
                return className + arraySuffix.toString();
            }
        }

        int lastDotIdx = className.lastIndexOf(PACKAGE_SEPARATOR_CHAR);
        int innerIdx = className.indexOf(
                INNER_CLASS_SEPARATOR_CHAR, lastDotIdx == -1 ? 0 : lastDotIdx + 1);
        String out = className.substring(lastDotIdx + 1);
        if (innerIdx != -1) {
            out = out.replace(INNER_CLASS_SEPARATOR_CHAR, PACKAGE_SEPARATOR_CHAR);
        }

        return out + arraySuffix.toString();
    }

public static String getPackageName(String className) {
    if (className == null || className.isEmpty()) { // Handle null and empty strings
        return ""; // Use "" instead of StringUtils.EMPTY for broader applicability
    }

    // Strip array encoding (e.g., "[Ljava.lang.String;")
    // Strip Object type encoding (e.g., "Ljava.lang.Object;")
    String processedClassName = className;
    if (processedClassName.startsWith("[L") && processedClassName.endsWith(";")) {
        processedClassName = processedClassName.substring(2, processedClassName.length() - 1);
    } else if (processedClassName.startsWith("L") && processedClassName.endsWith(";")) {
        processedClassName = processedClassName.substring(1, processedClassName.length() - 1);
    }

    int i = processedClassName.lastIndexOf(PACKAGE_SEPARATOR_CHAR);
    if (i == -1) {
        return ""; // No package separator found, so no package
    }
    return processedClassName.substring(0, i);
}

public static String abbreviate(String str, int lower, int upper, String appendToEnd) {
        // Initial parameter checks
        if (str == null) {
            return null;
        }
        if (str.length() == 0) {
            return StringUtils.EMPTY;
        }

        // Validate lower and upper bounds
        if (lower < 0) {
            throw new IllegalArgumentException("Parameter 'lower' cannot be negative.");
        }
        if (upper < -1) {
            throw new IllegalArgumentException("Parameter 'upper' cannot be negative unless it is -1 (no limit).");
        }

        // Adjust upper bound if it's -1 or exceeds string length
        int effectiveUpper = (upper == -1 || upper > str.length()) ? str.length() : upper;

        // Ensure lower is not greater than effectiveUpper
        // If lower is greater than effectiveUpper, it means we can't even reach lower,
        // so we should just truncate at effectiveUpper.
        int effectiveLower = Math.min(lower, effectiveUpper);

        // If the string is already shorter than or equal to the effective lower bound,
        // no abbreviation is needed.
        if (str.length() <= effectiveLower) {
            return str;
        }

        // Find the first space character within the range [effectiveLower, effectiveUpper]
        // or before effectiveUpper if no space is found after effectiveLower.
        int spaceIndex = -1;
        if (effectiveLower < str.length()) { // Only search if effectiveLower is within string bounds
            spaceIndex = StringUtils.indexOf(str, " ", effectiveLower);
        }

        StringBuilder result = new StringBuilder();
        String suffix = StringUtils.defaultString(appendToEnd);
        boolean abbreviated = false;

        if (spaceIndex == -1 || spaceIndex > effectiveUpper) {
            // No space found after effectiveLower, or the first space is beyond effectiveUpper.
            // Truncate at effectiveUpper.
            result.append(str.substring(0, effectiveUpper));
            abbreviated = (effectiveUpper < str.length());
        } else {
            // A space was found at or before effectiveUpper.
            // Truncate at this space index.
            result.append(str.substring(0, spaceIndex));
            abbreviated = true; // Truncated at a space, so it's an abbreviation
        }

        if (abbreviated) {
            result.append(suffix);
        }

        return result.toString();
    }

public static void escapeJava(Writer out, String str) throws IOException {
        if (out == null) {
            throw new IllegalArgumentException("The Writer must not be null.");
        }
        // Delegate to the private helper, ensuring single quotes are also escaped
        // for a robust "Java string literal" escaping.
        // If str is null, the helper should handle it gracefully (e.g., write nothing or empty string).
        // Assuming escapeJavaStyleString handles null str by writing nothing or an empty string.
        // If it doesn't, an explicit check for str == null should be added here.
        escapeJavaStyleString(out, str, true); // Changed to 'true' to escape single quotes
    }

public static String escapeJava(String str) {
    if (str == null) {
        return null;
    }
    // The underlying private method escapeJavaStyleString is assumed to handle
    // the actual escaping logic for backslashes, double quotes, control characters,
    // and Unicode characters, and to do so efficiently (e.g., using StringBuilder).
    // The 'false' argument indicates that single quotes should not be escaped,
    // which is appropriate for a string intended for a double-quoted Java literal.
    return escapeJavaStyleString(str, false);
}

public StrBuilder appendFixedWidthPadRight(Object obj, int width, char padChar) {
    // Robustness: Validate width to ensure it's a meaningful positive value.
    // A width of 0 or less doesn't make sense for "fixed-width" appending.
    if (width <= 0) {
        // If width is 0 or negative, we append nothing, which is consistent with the original behavior
        // but explicitly stating it here for clarity. Alternatively, an IllegalArgumentException
        // could be thrown if a positive width is strictly required.
        return this;
    }

    // Ensure enough capacity in the internal buffer for the new fixed-width string.
    ensureCapacity(size + width);

    // Get the string representation of the object. If obj is null, use the configured null text.
    String str = (obj == null ? getNullText() : obj.toString());
    int strLen = str.length();

    if (strLen >= width) {
        // If the string is longer than or equal to the desired width,
        // copy only the first 'width' characters to the buffer.
        str.getChars(0, width, buffer, size);
    } else {
        // If the string is shorter than the desired width,
        // copy the entire string and then pad the remaining space.
        int padLen = width - strLen;
        str.getChars(0, strLen, buffer, size);
        // Pad the remaining characters with 'padChar'.
        for (int i = 0; i < padLen; i++) {
            buffer[size + strLen + i] = padChar;
        }
    }
    // Update the internal size of the StrBuilder to reflect the appended fixed-width string.
    size += width;

    // Return 'this' for method chaining.
    return this;
}

public StrBuilder appendFixedWidthPadLeft(Object obj, int width, char padChar) {
    if (width < 0) {
        throw new IllegalArgumentException("Width must be non-negative.");
    }
    if (width == 0) {
        return this; // Append nothing if width is zero
    }

    ensureCapacity(size + width);
    String str = (obj == null ? getNullText() : obj.toString());
    int strLen = str.length();

    if (strLen >= width) {
        // Truncate from the left (keep rightmost 'width' characters)
        str.getChars(strLen - width, strLen, buffer, size);
    } else {
        // Pad on the left
        int padLen = width - strLen;
        for (int i = 0; i < padLen; i++) {
            buffer[size + i] = padChar;
        }
        str.getChars(0, strLen, buffer, size + padLen);
    }
    size += width;
    return this;
}

public Fraction reduce() {
    // Ensure the denominator is positive for canonical representation before reduction.
    // This also simplifies the GCD calculation as both inputs to GCD will be positive.
    int currentNumerator = this.numerator;
    int currentDenominator = this.denominator;

    if (currentDenominator < 0) {
        currentNumerator = -currentNumerator;
        currentDenominator = -currentDenominator;
    }

    // Calculate the greatest common divisor of the absolute numerator and the positive denominator.
    // The greatestCommonDivisor method is assumed to handle positive inputs correctly.
    int gcd = greatestCommonDivisor(Math.abs(currentNumerator), currentDenominator);

    // If the GCD is 1, the fraction is already in its simplest form.
    // Return the current instance to avoid creating a new identical object.
    if (gcd == 1) {
        // If the original fraction had a negative denominator and was normalized above,
        // we need to ensure we return the normalized version if it's different from 'this'.
        // However, the 'getFraction' method is the canonical way to create normalized fractions.
        // If 'this' was already normalized (positive denominator), then 'this' is correct.
        // If 'this' had a negative denominator, and gcd was 1, then 'this' is not reduced
        // to its canonical form (e.g., 1/-2 should become -1/2).
        // So, we should always use getFraction to ensure canonical form.
        if (currentNumerator == this.numerator && currentDenominator == this.denominator) {
            return this; // Already canonical and reduced
        } else {
            // The original fraction had a negative denominator but was already reduced (gcd=1).
            // Return the normalized version.
            return Fraction.getFraction(currentNumerator, currentDenominator);
        }
    }

    // Divide both numerator and denominator by their GCD to reduce the fraction.
    // The getFraction factory method will handle the creation of the new Fraction object,
    // including ensuring the denominator is positive and handling any potential sign issues
    // if the numerator becomes negative after division.
    return Fraction.getFraction(currentNumerator / gcd, currentDenominator / gcd);
}

public static Locale toLocale(final String str) {
        if (str == null) {
            return null;
        }

        final int len = str.length();

        // Minimum length for a language code is 2
        if (len < 2) {
            throw new IllegalArgumentException("Invalid locale format: String length must be at least 2 for language code. Input: '" + str + "'");
        }

        final char ch0 = str.charAt(0);
        final char ch1 = str.charAt(1);

        // Language code must be two lowercase letters
        if (!Character.isLowerCase(ch0) || !Character.isLowerCase(ch1)) {
            throw new IllegalArgumentException("Invalid locale format: Language code must be two lowercase letters. Input: '" + str + "'");
        }

        // Case 1: Language only (e.g., "en")
        if (len == 2) {
            return new Locale(str);
        }

        // At this point, length is > 2. Expecting '_' at index 2 for country or variant.
        if (str.charAt(2) != '_') {
            throw new IllegalArgumentException("Invalid locale format: Expected '_' separator at index 2 for country or variant. Input: '" + str + "'");
        }

        // Check for language_COUNTRY or language_COUNTRY_variant
        // Minimum length for language_COUNTRY is 5 (ll_CC)
        if (len < 5) {
            // This covers cases like "en_", "en_U", "en_US" (if len was 4, which is invalid)
            throw new IllegalArgumentException("Invalid locale format: String length must be at least 5 for language_COUNTRY. Input: '" + str + "'");
        }

        final char ch3 = str.charAt(3);
        final char ch4 = str.charAt(4);

        // Case 2: language_COUNTRY (e.g., "en_US") or language_COUNTRY_variant (e.g., "en_US_MAC")
        // Country code must be two uppercase letters
        if (Character.isUpperCase(ch3) && Character.isUpperCase(ch4)) {
            // If length is exactly 5, it's language_COUNTRY
            if (len == 5) {
                return new Locale(str.substring(0, 2), str.substring(3, 5));
            }

            // If length is > 5, check for variant
            if (str.charAt(5) != '_') {
                throw new IllegalArgumentException("Invalid locale format: Expected '_' separator at index 5 for variant. Input: '" + str + "'");
            }

            // Case 3: language_COUNTRY_variant (e.g., "en_US_MAC")
            // Variant can be any length after the second underscore
            return new Locale(str.substring(0, 2), str.substring(3, 5), str.substring(6));
        }
        // Case 4: language__variant (e.g., "en__MAC") - no country code
        // This implies ch3 and ch4 are NOT both uppercase.
        // If ch3 is an underscore, it's "ll__variant"
        else if (ch3 == '_') {
            // The format is "ll__variant". The country code is empty.
            // The variant starts at index 4.
            // Minimum length for "ll__v" is 5.
            if (len < 5) {
                throw new IllegalArgumentException("Invalid locale format: String length must be at least 5 for language__variant. Input: '" + str + "'");
            }
            return new Locale(str.substring(0, 2), "", str.substring(4));
        }
        // If ch3 and ch4 are not both uppercase, and ch3 is not '_', then it's an invalid country code.
        else {
            throw new IllegalArgumentException("Invalid locale format: Country code must be two uppercase letters or an empty string indicated by '__'. Input: '" + str + "'");
        }
    }

public static synchronized FastDateFormat getDateTimeInstance(int dateStyle, int timeStyle, TimeZone timeZone,
            Locale locale) {

        // Validate dateStyle and timeStyle
        if (!isValidStyle(dateStyle) && dateStyle != -1) { // -1 could be a sentinel for no date style
            throw new IllegalArgumentException("Invalid dateStyle: " + dateStyle);
        }
        if (!isValidStyle(timeStyle) && timeStyle != -1) { // -1 could be a sentinel for no time style
            throw new IllegalArgumentException("Invalid timeStyle: " + timeStyle);
        }

