        // Construct a robust cache key that includes all relevant parameters
        // The key should reflect the *resolved* locale.
        Object key = new Pair(new Integer(dateStyle), new Integer(timeStyle));
        if (timeZone != null) {
            key = new Pair(key, timeZone);
