                // This will handle the combination of dateStyle and timeStyle correctly.
                // The cast to SimpleDateFormat is generally safe for standard JREs.
                SimpleDateFormat formatter = (SimpleDateFormat) DateFormat.getDateTimeInstance(dateStyle, timeStyle,
                        resolvedLocale);
                String pattern = formatter.toPattern();

                // Create the FastDateFormat instance using the obtained pattern and resolved parameters
                format = getInstance(pattern, timeZone, resolvedLocale);

                // Store the newly created instance in the cache
                cDateTimeInstanceCache.put(key, format);

            } catch (ClassCastException ex) {
                // This exception indicates that DateFormat.getDateTimeInstance did not return a SimpleDateFormat,
                // which is unexpected in standard Java environments.
                throw new IllegalArgumentException("Failed to obtain SimpleDateFormat pattern for locale: " + resolvedLocale +
                                                   ". Underlying DateFormat.getDateTimeInstance returned an unexpected type.", ex);
            } catch (IllegalArgumentException ex) {
                // Catch potential IllegalArgumentException from DateFormat.getDateTimeInstance
                // for invalid styles or other issues.
                throw new IllegalArgumentException("Error creating date/time formatter for dateStyle: " + dateStyle +
                                                   ", timeStyle: " + timeStyle + ", locale: " + resolvedLocale, ex);
            }
        }
        return format;
    }

public static synchronized FastDateFormat getDateInstance(int style, TimeZone timeZone, Locale locale) {
        // 1. Input Validation for style
        if (style < 0 || style > DateFormat.FULL) { // Assuming DateFormat.FULL is the max valid style
            throw new IllegalArgumentException("Invalid date style: " + style);
        }

        // 2. Construct a robust and consistent cache key
        // We'll build the key in a consistent order: style, timeZone, locale
        // Using a custom Pair class with proper equals/hashCode is essential.
        Object key = Integer.valueOf(style); // Use Integer.valueOf for potential caching of Integer objects

        if (timeZone != null) {
            key = new Pair(key, timeZone);
        }

        if (locale != null) {
            key = new Pair(key, locale);
        }

        FastDateFormat format = cDateInstanceCache.get(key);
        if (format == null) {
            Locale effectiveLocale = (locale != null) ? locale : Locale.getDefault();

            try {
                // DateFormat.getDateInstance is not guaranteed to return SimpleDateFormat.
                // We need to get the pattern string from it.
                DateFormat dateFormat = DateFormat.getDateInstance(style, effectiveLocale);

                // Check if it's a SimpleDateFormat to get the pattern.
