                    // into a FastDateFormat using a pattern.
                    // Depending on requirements, this could be an error or a fallback.
                    // For now, we'll throw an exception as the original code implies
                    // a pattern is always derivable.
                    throw new IllegalArgumentException("Cannot obtain pattern from DateFormat for style: " + style + ", locale: " + effectiveLocale);
                }

                SimpleDateFormat simpleDateFormat = (SimpleDateFormat) dateFormat;
                String pattern = simpleDateFormat.toPattern();

                // Use the internal getInstance method to create the FastDateFormat
                // This ensures consistency and potential caching within getInstance(pattern, ...)
                format = getInstance(pattern, timeZone, effectiveLocale);
                cDateInstanceCache.put(key, format);

            } catch (ClassCastException ex) {
                // This catch block is now less likely due to the explicit instanceof check,
                // but kept for robustness if the check is bypassed or for other unexpected casts.
                throw new IllegalArgumentException("Failed to cast DateFormat to SimpleDateFormat for locale: " + effectiveLocale, ex);
            } catch (IllegalArgumentException ex) {
                // Catch potential IllegalArgumentException from DateFormat.getDateInstance
                // or from our own pattern derivation failure.
                throw new IllegalArgumentException("Error getting date instance for style: " + style + ", locale: " + effectiveLocale, ex);
            }
        }
        return format;
    }

public static boolean toBoolean(String str) {
    if (str == null) {
        return false;
    }

    // Use equalsIgnoreCase for "true" to handle all case variations consistently
    // and avoid reliance on string interning.
    // This also simplifies the case 4 logic.
    if ("true".equalsIgnoreCase(str)) {
        return true;
    }

    switch (str.length()) {
        case 2: { // Handles "on", "ON", "On", "oN"
            char ch0 = str.charAt(0);
            char ch1 = str.charAt(1);
            return
                (ch0 == 'o' || ch0 == 'O') &&
                (ch1 == 'n' || ch1 == 'N');
        }
        case 3: { // Handles "yes", "YES", "yEs", "yeS", etc.
            // Simplified and more robust character comparison for all cases
            return
                (str.charAt(0) == 'y' || str.charAt(0) == 'Y') &&
                (str.charAt(1) == 'e' || str.charAt(1) == 'E') &&
                (str.charAt(2) == 's' || str.charAt(2) == 'S');
        }
        // Case 4 for "true" is now handled by the initial equalsIgnoreCase check.
        // If we wanted to handle other 4-letter "truthy" strings, they would go here.
        // Since the original only handled "true", and that's now covered, this case can be removed
        // or left empty if no other 4-letter truthy strings are intended.
        // For clarity and to reflect the original intent (only "true" for length 4),
        // we can remove the explicit case 4 block as it's now redundant.
    }
    return false;
}

public void stop() {
    // Ensure the stopwatch is in a state where it can be stopped.
    // It must be either running or suspended.
    if (this.runningState != STATE_RUNNING && this.runningState != STATE_SUSPENDED) {
        throw new IllegalStateException("Stopwatch is not running or suspended. Cannot stop.");
    }

    // Record the time when the stopwatch is stopped.
    stopTime = System.currentTimeMillis();

    // Transition the stopwatch to the stopped state.
    this.runningState = STATE_STOPPED;

    // Reset the split state, as stopping the stopwatch typically implies
    // that any previously recorded split times are no longer relevant
    // for the current timing session.
    this.splitState = STATE_UNSPLIT;
}

public static boolean isAvailableLocale(Locale locale) {
