        // Robustness: Ensure cAvailableLocaleSet is not null before calling contains.
        // While cAvailableLocaleSet is static final and initialized, this check
        // adds an extra layer of safety against highly unusual initialization failures.
        // In most cases, this check is redundant for static final fields.
        if (cAvailableLocaleSet == null) {
