            // might be more appropriate than just returning false.
            // For a simple availability check, returning false is a safe fallback.
            return false;
        }
        return cAvailableLocaleSet.contains(locale);
    }

public static Number createNumber(String str) throws NumberFormatException {
        if (str == null) {
            return null;
        }
        if (isBlank(str)) {
            throw new NumberFormatException("A blank string is not a valid number");
        }

        // Protection for BigDecimal's potential quirks with "--"
        // If this format is truly invalid, throw an exception.
        // BigDecimal itself will throw if it cannot parse.
        if (str.startsWith("--")) {
            throw new NumberFormatException("String starts with '--', which is not a valid number format.");
        }

        // Handle hexadecimal numbers
        if (str.startsWith("0x") || str.startsWith("-0x")) {
            try {
                return createInteger(str); // Assuming createInteger handles hex (e.g., via Integer.decode)
            } catch (NumberFormatException e) {
                // If it's too large for an Integer, try BigInteger
                try {
                    return createBigInteger(str);
                } catch (NumberFormatException bigIntEx) {
                    throw new NumberFormatException("Invalid hexadecimal number: " + str);
                }
            }
        }

        char lastChar = str.charAt(str.length() - 1);
        String mant;
        String dec;
        String exp;
        int decPos = str.indexOf('.');
        // Corrected expPos calculation
        int expPos = Math.max(str.indexOf('e'), str.indexOf('E'));

        if (decPos > -1) {
            if (expPos > -1) {
                if (expPos < decPos) {
                    throw new NumberFormatException(str + " is not a valid number. Exponent before decimal point.");
                }
                dec = str.substring(decPos + 1, expPos);
            } else {
                dec = str.substring(decPos + 1);
            }
            mant = str.substring(0, decPos);
        } else {
            if (expPos > -1) {
                mant = str.substring(0, expPos);
            } else {
                mant = str;
            }
            dec = null;
        }

        // Check if the last character is a digit or a type suffix
        if (!Character.isDigit(lastChar)) {
            String numeric = str.substring(0, str.length() - 1);

            // Extract exponent part if present
            if (expPos > -1 && expPos < str.length() - 1) {
                exp = str.substring(expPos + 1, str.length() - 1); // Exponent without the suffix
            } else {
                exp = null;
            }

            // Guard against NullPointerException for isAllZeros
            boolean allZeros = (mant != null && isAllZeros(mant)) && (exp == null || isAllZeros(exp));

            switch (lastChar) {
                case 'l':
                case 'L':
                    // Check for valid long format: no decimal, no exponent, and numeric part is digits (allowing leading minus)
                    if (dec == null && exp == null) {
                        String checkNumeric = numeric.startsWith("-") ? numeric.substring(1) : numeric;
                        if (isDigits(checkNumeric)) {
                            try {
                                return createLong(numeric);
                            } catch (NumberFormatException nfe) {
                                // Too big for a long, try BigInteger
                                try {
                                    return createBigInteger(numeric);
                                } catch (NumberFormatException bigIntEx) {
                                    throw new NumberFormatException("Invalid BigInteger format for '" + str + "'", bigIntEx);
                                }
                            }
                        }
                    }
                    throw new NumberFormatException(str + " is not a valid long number format.");

                case 'f':
                case 'F':
                    try {
                        Float f = createFloat(numeric);
                        // Check for infinity, or zero with non-zero original value (precision loss/underflow)
                        // Also check for precision loss for non-zero, non-infinite numbers
                        BigDecimal bd = createBigDecimal(numeric);
                        if (!f.isInfinite() && !(f.floatValue() == 0.0F && !allZeros) && bd.compareTo(new BigDecimal(f.toString())) == 0) {
                            return f;
                        }
                    } catch (NumberFormatException nfe) {
                        // Fall through to try Double/BigDecimal if Float parsing fails
                    }
                    // Fall through to 'd' case to try Double/BigDecimal if Float is not suitable or fails
                case 'd':
                case 'D':
                    try {
                        Double d = createDouble(numeric);
                        // Check for infinity, or zero with non-zero original value (precision loss/underflow)
                        // Also check for precision loss for non-zero, non-infinite numbers
                        BigDecimal bd = createBigDecimal(numeric);
                        if (!d.isInfinite() && !(d.doubleValue() == 0.0D && !allZeros) && bd.compareTo(new BigDecimal(d.toString())) == 0) {
                            return d;
                        }
                    } catch (NumberFormatException nfe) {
                        // Fall through to try BigDecimal if Double parsing fails
                    }
                    try {
                        return createBigDecimal(numeric);
                    } catch (NumberFormatException e) {
                        throw new NumberFormatException("Invalid floating point number with suffix: '" + str + "'", e);
                    }

                default:
                    throw new NumberFormatException(str + " is not a valid number. Unknown suffix '" + lastChar + "'.");
            }
        } else {
            // User doesn't have a preference on the return type, so let's start
            // small and go from there...
            if (expPos > -1 && expPos < str.length()) { // expPos can be at the end of the string
                exp = str.substring(expPos + 1);
            } else {
                exp = null;
            }

            if (dec == null && exp == null) {
                // Must be an int, long, BigInteger
                try {
                    return createInteger(str);
                } catch (NumberFormatException nfe) {
                    // ignore, try next
                }
                try {
                    return createLong(str);
                } catch (NumberFormatException nfe) {
                    // ignore, try next
                }
                try {
                    return createBigInteger(str);
                } catch (NumberFormatException nfe) {
                    throw new NumberFormatException("Invalid integer number: '" + str + "'", nfe);
                }
            } else {
                // Must be a float, double, BigDecimal
                boolean allZeros = (mant != null && isAllZeros(mant)) && (exp == null || isAllZeros(exp));
                try {
                    Float f = createFloat(str);
                    // Check for infinity, or zero with non-zero original value (precision loss/underflow)
                    // Also check for precision loss for non-zero, non-infinite numbers
                    BigDecimal bd = createBigDecimal(str);
                    if (!f.isInfinite() && !(f.floatValue() == 0.0F && !allZeros) && bd.compareTo(new BigDecimal(f.toString())) == 0) {
                        return f;
                    }
                } catch (NumberFormatException nfe) {
                    // ignore, try next
                }
                try {
                    Double d = createDouble(str);
                    // Check for infinity, or zero with non-zero original value (precision loss/underflow)
                    // Also check for precision loss for non-zero, non-infinite numbers
                    BigDecimal bd = createBigDecimal(str);
                    if (!d.isInfinite() && !(d.doubleValue() == 0.0D && !allZeros) && bd.compareTo(new BigDecimal(d.toString())) == 0) {
                        return d;
                    }
                } catch (NumberFormatException nfe) {
                    // ignore, try next
                }
                try {
                    return createBigDecimal(str);
                } catch (NumberFormatException nfe) {
                    throw new NumberFormatException("Invalid floating point number: '" + str + "'", nfe);
                }
            }
        }
    }

public StrBuilder appendFixedWidthPadRight(Object obj, int width, char padChar) {
    if (width <= 0) {
        return this; // No-op if width is non-positive
    }

    ensureCapacity(size + width); // Ensure enough capacity for the fixed width

    String str = (obj == null ? getNullText() : obj.toString());
    int strLen = str.length();

    if (strLen >= width) {
        // If string is longer or equal to width, truncate and append the first 'width' characters
        str.getChars(0, width, buffer, size);
    } else {
        // If string is shorter than width, append the string and then pad with padChar
        str.getChars(0, strLen, buffer, size);
        int padLen = width - strLen;
        for (int i = 0; i < padLen; i++) {
            buffer[size + strLen + i] = padChar;
        }
    }
    size += width; // Update the size of the StrBuilder by the fixed width
    return this;
}

public int indexOf(char ch, int startIndex) {
    // Ensure startIndex is not negative. If it is, start from the beginning.
    startIndex = (startIndex < 0 ? 0 : startIndex);

    // If the startIndex is beyond the current size of the StrBuilder,
    // the character cannot be found, so return -1.
    if (startIndex >= size) {
        return -1;
    }

    // Get a reference to the internal character buffer for efficiency.
    char[] thisBuf = buffer;

    // Iterate from the adjusted startIndex up to the actual size of the StrBuilder content.
    for (int i = startIndex; i < size; i++) { // Corrected loop termination condition
        if (thisBuf[i] == ch) {
            return i; // Character found at index i
        }
    }

    // Character not found within the specified range.
    return -1;
}

