}

public int indexOf(String str, int startIndex) {
    // Ensure startIndex is not negative.
    startIndex = Math.max(0, startIndex);

    // Handle null search string.
    if (str == null) {
        return -1;
    }

    int strLen = str.length();

    // Handle empty search string.
    // An empty string is always found at startIndex, provided startIndex is within bounds.
    if (strLen == 0) {
        return (startIndex <= size) ? startIndex : -1;
    }

    // If the search string is longer than the remaining content from startIndex, it cannot be found.
    if (strLen > size - startIndex) {
        return -1;
    }

    // Optimization for single character search.
    // This delegates to an existing optimized method for single characters.
    if (strLen == 1) {
        return indexOf(str.charAt(0), startIndex);
    }

    // Get the internal buffer. Assuming 'buffer' is never null due to StrBuilder's design.
    // If 'buffer' could be null, an additional check would be needed here.
    char[] thisBuf = buffer;

    // The maximum starting index for a match.
    // We search up to (size - strLen) because a match of length strLen starting
    // at (size - strLen) would end at (size - 1).
    int limit = size - strLen;

    outer:
    for (int i = startIndex; i <= limit; i++) {
        for (int j = 0; j < strLen; j++) {
            if (str.charAt(j) != thisBuf[i + j]) {
                continue outer; // Mismatch, try next starting position in outer loop
            }
        }
        return i; // Full match found
    }

    return -1; // No match found
}

public static String formatPeriod(long startMillis, long endMillis, String format, boolean padWithZeros,
                                  TimeZone timezone) {

    // Robustness: Input validation
    if (format == null || format.isEmpty()) {
        return ""; // Or throw IllegalArgumentException, depending on desired behavior for empty format
    }
    if (timezone == null) {
        throw new IllegalArgumentException("TimeZone cannot be null.");
    }

    // If startMillis is greater than endMillis, swap them to ensure a positive duration.
    // The method is intended to format a duration, not a negative period.
    if (startMillis > endMillis) {
        long temp = startMillis;
        startMillis = endMillis;
        endMillis = temp;
    }

    // The initial check for < 28 days and delegating to formatDuration is a logical flaw
    // for a method designed to handle calendar periods. We should always use calendar-aware logic.
    // The original code's comment "timezones get funky around 0, so normalizing everything to GMT
    // stops the hours being off" suggests a potential issue with Calendar.getInstance() and timezones.
    // However, Calendar.getInstance(timezone) should correctly handle the specified timezone.
    // The "normalization to GMT" comment might be a misunderstanding or a workaround for a specific bug
    // in an older Calendar implementation. For robust period calculation, we should use the provided timezone.

    Calendar start = Calendar.getInstance(timezone);
    start.setTime(new Date(startMillis));
    Calendar end = Calendar.getInstance(timezone);
    end.setTime(new Date(endMillis));

    // Initialize differences. These will be adjusted.
    int years = 0;
    int months = 0;
    int days = 0;
    int hours = 0;
    int minutes = 0;
    int seconds = 0;
    int milliseconds = 0;

    // Calculate differences by iterating from the smallest unit to the largest,
    // borrowing from higher units as needed. This is a more robust approach than
    // the original's initial estimates followed by multiple while loops and reduceAndCorrect.

    // Milliseconds
    milliseconds = end.get(Calendar.MILLISECOND) - start.get(Calendar.MILLISECOND);
    if (milliseconds < 0) {
        milliseconds += 1000;
        end.add(Calendar.SECOND, -1); // Borrow from seconds
    }

    // Seconds
    seconds = end.get(Calendar.SECOND) - start.get(Calendar.SECOND);
    if (seconds < 0) {
        seconds += 60;
        end.add(Calendar.MINUTE, -1); // Borrow from minutes
    }

    // Minutes
    minutes = end.get(Calendar.MINUTE) - start.get(Calendar.MINUTE);
    if (minutes < 0) {
        minutes += 60;
        end.add(Calendar.HOUR_OF_DAY, -1); // Borrow from hours
    }

    // Hours
    hours = end.get(Calendar.HOUR_OF_DAY) - start.get(Calendar.HOUR_OF_DAY);
    if (hours < 0) {
        hours += 24;
        end.add(Calendar.DAY_OF_MONTH, -1); // Borrow from days
    }

    // Days
    // This is the trickiest part due to varying month lengths.
    // We calculate the difference in days, then adjust months and years.
    days = end.get(Calendar.DAY_OF_MONTH) - start.get(Calendar.DAY_OF_MONTH);
    if (days < 0) {
        // The number of days to add depends on the previous month's length.
        // We need to move 'end' back by one month to get the correct number of days to borrow.
        Calendar tempEnd = (Calendar) end.clone();
        tempEnd.add(Calendar.MONTH, -1);
        days += tempEnd.getActualMaximum(Calendar.DAY_OF_MONTH);
        end.add(Calendar.MONTH, -1); // Borrow from months
    }

    // Months
    months = end.get(Calendar.MONTH) - start.get(Calendar.MONTH);
    if (months < 0) {
        months += 12;
        end.add(Calendar.YEAR, -1); // Borrow from years
    }

    // Years
    years = end.get(Calendar.YEAR) - start.get(Calendar.YEAR);

    // At this point, years, months, days, hours, minutes, seconds, milliseconds
    // represent the "normalized" differences, where each unit is positive and
    // within its natural range (e.g., 0-11 for months, 0-23 for hours).

    // Now, apply the logic for combining units if they are not requested in the format string.
    // This part needs to be careful about the order of operations and leap years.

    Token[] tokens = lexx(format);

    // Convert higher units to lower units if the higher unit is not requested.
    // Process from largest to smallest unit to ensure correct cascading.

    // Years to Months/Days
    if (!containsTokenWithValue(tokens, y)) {
        if (containsTokenWithValue(tokens, M)) {
            months += years * 12;
        } else {
            // If neither years nor months are requested, convert years to days.
            // This requires a more accurate calculation considering leap years.
            // Iterate through the years to sum up days.
            Calendar tempStart = (Calendar) start.clone();
            for (int i = 0; i < years; i++) {
                days += tempStart.getActualMaximum(Calendar.DAY_OF_YEAR); // Adds 365 or 366
                tempStart.add(Calendar.YEAR, 1);
            }
        }
        years = 0; // Years have been absorbed
    }

    // Months to Days
    if (!containsTokenWithValue(tokens, M)) {
        // If months are not requested, convert remaining months to days.
        // This needs to be done carefully, considering the specific months involved.
        // The original logic `end.get(Calendar.DAY_OF_YEAR) - start.get(Calendar.DAY_OF_YEAR)` is flawed.
        // Instead, we should iterate through the months and add their actual day counts.
        Calendar tempStart = (Calendar) start.clone();
        tempStart.add(Calendar.YEAR, years); // Move to the same year as 'end' after year calculation
        for (int i = 0; i < months; i++) {
            days += tempStart.getActualMaximum(Calendar.DAY_OF_MONTH);
            tempStart.add(Calendar.MONTH, 1);
        }
        months = 0; // Months have been absorbed
    }

    // Days to Hours
    if (!containsTokenWithValue(tokens, d)) {
        hours += days * 24;
        days = 0;
    }

    // Hours to Minutes
    if (!containsTokenWithValue(tokens, H)) {
        minutes += hours * 60;
        hours = 0;
    }

    // Minutes to Seconds
    if (!containsTokenWithValue(tokens, m)) {
        seconds += minutes * 60;
        minutes = 0;
    }

    // Seconds to Milliseconds
    if (!containsTokenWithValue(tokens, s)) {
        milliseconds += seconds * 1000;
        seconds = 0;
    }

    // Finally, format the calculated components.
    return format(tokens, years, months, days, hours, minutes, seconds, milliseconds, padWithZeros);
}

public int compareTo(Object other) {
    // Robustness Omission 1: Null Check for 'other'
    if (other == null) {
        throw new NullPointerException("Cannot compare ValuedEnum to null.");
    }

    // Robustness Omission 2: Type Check for 'other'
    // The Comparable contract allows ClassCastException if types are incomparable.
    // Explicitly checking and casting ensures we only compare with compatible types.
    if (!(other instanceof ValuedEnum)) {
        throw new ClassCastException("Cannot compare ValuedEnum to an object of type " + other.getClass().getName() + ". Expected ValuedEnum.");
    }

    ValuedEnum otherValuedEnum = (ValuedEnum) other;

    // Logical Mistake 1: Violation of compareTo Contract (Transitivity and Consistency)
    // Using Integer.compare to avoid potential integer overflow/underflow issues
    // that can arise from direct subtraction, ensuring the compareTo contract is met.
    return Integer.compare(this.iValue, otherValuedEnum.iValue);
}

public static Number createNumber(String str) throws NumberFormatException {
        if (str == null) {
            return null;
        }
        if (isBlank(str)) {
            throw new NumberFormatException("A blank string is not a valid number.");
        }
        // Disallow "--" as it's ambiguous and not a standard number format
        if (str.startsWith("--")) {
            throw new NumberFormatException("String starts with '--', which is not a valid number format: " + str);
        }

        // Handle hexadecimal numbers
        if (str.startsWith("0x") || str.startsWith("-0x") || str.startsWith("0X") || str.startsWith("-0X")) {
            String hexPart = str.startsWith("-") ? str.substring(3) : str.substring(2);
            // Check if it fits in an Integer or Long based on length and potential value range
            // A more robust check would involve parsing and then checking range, but for length-based,
            // 8 hex digits (excluding 0x/0X and sign) is max for int, 16 for long.
            // This is a simplification, actual value check is better.
            if (hexPart.length() > 16) { // Too many for a long
                return createBigInteger(str);
            } else if (hexPart.length() > 8) { // Too many for an int, but fits in long
                return createLong(str);
            }
            // Try Integer first, then Long if Integer fails (e.g., for 0x80000000)
            try {
                return createInteger(str);
            } catch (NumberFormatException nfe) {
                // If it didn't fit in an Integer, try Long
                return createLong(str);
            }
        }

        char lastChar = str.charAt(str.length() - 1);
        String mant;
        String dec;
        String exp;
        int decPos = str.indexOf('.');
        int expPosE = str.indexOf('e');
        int expPosUpperE = str.indexOf('E');
        int expPos = Math.max(expPosE, expPosUpperE); // Correctly find the first 'e' or 'E'

        // Validate decimal and exponent positions
        if (decPos > -1 && expPos > -1 && decPos > expPos) {
            throw new NumberFormatException("Decimal point cannot appear after exponent: " + str);
        }

        if (decPos > -1) { // Contains a decimal point
            if (expPos > -1) { // Contains an exponent
                dec = str.substring(decPos + 1, expPos);
                mant = str.substring(0, decPos);
            } else { // Only decimal point
                dec = str.substring(decPos + 1);
                mant = str.substring(0, decPos);
            }
        } else { // No decimal point
            if (expPos > -1) { // Only exponent
                mant = str.substring(0, expPos);
                dec = null; // No decimal part
            } else { // Neither decimal nor exponent
                mant = str;
                dec = null;
            }
        }

        // Extract exponent part if present
        if (expPos > -1) {
            exp = str.substring(expPos + 1);
        } else {
            exp = null;
        }

        // Handle numbers with type suffixes (l, L, f, F, d, D)
        if (!Character.isDigit(lastChar) && lastChar != '.') {
            String numeric = str.substring(0, str.length() - 1);
            boolean allZeros = isAllZeros(mant) && isAllZeros(dec) && isAllZeros(exp); // Check all parts

            switch (lastChar) {
                case 'l':
                case 'L':
                    // A long literal cannot have a decimal or exponent part
                    if (dec != null || exp != null) {
                        throw new NumberFormatException("Long literal cannot contain decimal or exponent: " + str);
                    }
                    // Ensure the numeric part is a valid integer format
                    if (!isDigits(numeric) && !(numeric.startsWith("-") && isDigits(numeric.substring(1)))) {
                        throw new NumberFormatException("Invalid numeric part for Long literal: " + str);
                    }
                    try {
                        return createLong(numeric);
                    } catch (NumberFormatException nfe) {
                        // Too big for a long, try BigInteger
                        return createBigInteger(numeric);
                    }
                case 'f':
                case 'F':
                    try {
                        Float f = createFloat(numeric);
                        // Check for infinity or loss of precision (0.0F from non-zero string)
                        if (!f.isInfinite() && !(f.floatValue() == 0.0F && !allZeros)) {
                            return f;
                        }
                    } catch (NumberFormatException nfe) {
                        // Ignore and fall through to double/BigDecimal
                    }
                    // FALL-THROUGH to 'd'/'D' case if float fails or is imprecise
                case 'd':
                case 'D':
                    try {
                        Double d = createDouble(numeric);
                        // Corrected: use d.doubleValue()
                        if (!d.isInfinite() && !(d.doubleValue() == 0.0D && !allZeros)) {
                            return d;
                        }
                    } catch (NumberFormatException nfe) {
                        // Ignore and fall through to BigDecimal
                    }
                    // If float/double failed or were imprecise, try BigDecimal
                    try {
                        return createBigDecimal(numeric);
                    } catch (NumberFormatException e) {
                        throw new NumberFormatException("Could not parse '" + str + "' as a BigDecimal after float/double attempts: " + e.getMessage());
                    }
                default:
                    throw new NumberFormatException("Invalid number format with unknown suffix: " + str);
            }
        } else { // No type suffix, determine type automatically
            boolean allZeros = isAllZeros(mant) && isAllZeros(dec) && isAllZeros(exp);

            if (dec == null && exp == null) { // Integer-like number
                try {
                    return createInteger(str);
                } catch (NumberFormatException nfe) {
                    // Ignore and try Long
                }
                try {
                    return createLong(str);
                } catch (NumberFormatException nfe) {
                    // Ignore and try BigInteger
                }
                return createBigInteger(str);
            } else { // Floating-point like number
                try {
                    Float f = createFloat(str);
                    if (!f.isInfinite() && !(f.floatValue() == 0.0F && !allZeros)) {
                        return f;
                    }
                } catch (NumberFormatException nfe) {
                    // Ignore and try Double
                }
                try {
                    Double d = createDouble(str);
                    if (!d.isInfinite() && !(d.doubleValue() == 0.0D && !allZeros)) { // Corrected: d.doubleValue()
                        return d;
                    }
                } catch (NumberFormatException nfe) {
                    // Ignore and try BigDecimal
                }
                return createBigDecimal(str);
            }
        }
    }
